use std::path::PathBuf;

#[derive(Debug, PartialEq)]
pub struct Config {
    pub query: String,
    pub path: PathBuf,
    pub ignore_case: bool,
}
impl Config {
    pub fn parse(
        args: impl IntoIterator<Item = String>,
    ) -> Result<Self, &'static str> {
        let mut positional = Vec::new();
        let mut ignore_case = false;
        let mut options = true;
        for arg in args {
            match arg.as_str() {
                "--" if options => options = false,
                "--ignore-case" if options => ignore_case = true,
                _ if options && arg.starts_with('-') => {
                    return Err("unknown option");
                }
                _ => positional.push(arg),
            }
        }
        if positional.len() != 2 {
            return Err("expected QUERY FILE");
        }
        let mut args = positional.into_iter();
        Ok(Self {
            query: args.next().unwrap(),
            path: args.next().unwrap().into(),
            ignore_case,
        })
    }
}

/// Returned lines borrow the input text, not the query.
///
/// ```
/// assert_eq!(minigrep::search("safe", "safe Rust\nfast", false), vec!["safe Rust"]);
/// ```
pub fn search<'a>(
    query: &str,
    text: &'a str,
    ignore_case: bool,
) -> Vec<&'a str> {
    let normalized = if ignore_case {
        query.to_lowercase()
    } else {
        query.to_owned()
    };
    text.lines()
        .filter(|line| {
            if ignore_case {
                line.to_lowercase().contains(&normalized)
            } else {
                line.contains(&normalized)
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    fn args(values: &[&str]) -> Vec<String> {
        values.iter().map(|s| s.to_string()).collect()
    }
    #[test]
    fn flags_and_arity() {
        let c = Config::parse(args(&[
            "--ignore-case",
            "rust",
            "input.txt",
        ]))
        .unwrap();
        assert!(c.ignore_case);
        assert_eq!(c.path, PathBuf::from("input.txt"));
        assert!(Config::parse(args(&["rust"])).is_err());
        assert!(
            Config::parse(args(&["--unknown", "rust", "input.txt"]))
                .is_err()
        );
        assert!(
            Config::parse(args(&["rust", "input.txt", "extra"]))
                .is_err()
        );
    }
    #[test]
    fn end_of_options() {
        assert_eq!(
            Config::parse(args(&["--", "-n", "file"])).unwrap().query,
            "-n"
        );
    }
    #[test]
    fn case_sensitive_and_insensitive() {
        let text = "Rust is fast\nrust is safe\nOCaml is expressive\n";
        assert_eq!(search("rust", text, false), vec!["rust is safe"]);
        assert_eq!(
            search("RUST", text, true),
            vec!["Rust is fast", "rust is safe"]
        );
    }
    #[test]
    fn empty_crlf_and_unicode() {
        assert!(search("", "", false).is_empty());
        assert_eq!(search("", "a\r\nb\r\n", false), vec!["a", "b"]);
        assert_eq!(search("É", "été\n雪", true), vec!["été"]);
    }
    #[test]
    fn results_outlive_temporary_query() {
        let text = String::from("Rust\nOCaml");
        let result = {
            let query = String::from("Rust");
            search(&query, &text, false)
        };
        assert_eq!(result, vec!["Rust"]);
    }
}

use minigrep::{Config, search};
use std::{env, fs, process::ExitCode};
fn main() -> ExitCode {
    let args = env::args_os()
        .skip(1)
        .map(|a| a.into_string().map_err(|_| "arguments must be UTF-8"))
        .collect::<Result<Vec<_>, _>>();
    let config = match args.and_then(Config::parse) {
        Ok(c) => c,
        Err(e) => {
            eprintln!(
                "usage: minigrep [--ignore-case] [--] QUERY FILE\n{e}"
            );
            return ExitCode::from(2);
        }
    };
    let text = match fs::read_to_string(&config.path) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("read error: {e}");
            return ExitCode::FAILURE;
        }
    };
    for line in search(&config.query, &text, config.ignore_case) {
        println!("{line}");
    }
    ExitCode::SUCCESS
}

