/// Return every line not selected by the ordinary search.
pub fn search_inverted<'a>(
    query: &str,
    text: &'a str,
    ignore_case: bool,
) -> Vec<&'a str> {
    let normalized = if ignore_case {
        query.to_lowercase()
    } else {
        query.to_owned()
    };
    text.lines()
        .filter(|line| {
            let matched = if ignore_case {
                line.to_lowercase().contains(&normalized)
            } else {
                line.contains(&normalized)
            };
            !matched
        })
        .collect()
}
