            vec!["OCaml"]
        );
        assert_eq!(
            search_inverted("", "a\nb", false),
            Vec::<&str>::new()
        );
        let config = Config::parse(
            ["--invert", "rust", "file"].map(String::from),
        )
        .unwrap();
        assert!(config.invert);
    }
