use std::{env, fs, path::PathBuf};
fn main() {
    println!("cargo::rerun-if-changed=build.rs");
    println!("cargo::rustc-check-cfg=cfg(engine_checked)");
    let checked = env::var_os("CARGO_FEATURE_CHECKED").is_some();
    if checked {
        println!("cargo::rustc-cfg=engine_checked");
    }
    let mode = if checked { "checked" } else { "wrapping" };
    let generated = format!("pub const MODE: &str = {mode:?};\n");
    let output = PathBuf::from(
        env::var_os("OUT_DIR").expect("Cargo sets OUT_DIR"),
    );
    fs::write(output.join("mode.rs"), generated)
        .expect("write generated source");
}

include!(concat!(env!("OUT_DIR"), "/mode.rs"));

/// The default uses explicit wrapping arithmetic; checked reports overflow.
/// ```
/// assert_eq!(feature_engine::sum(&[1,2,3]), Ok(6));
/// ```
pub fn sum(values: &[u8]) -> Result<u8, &'static str> {
    let mut total = 0u8;
    for &value in values {
        #[cfg(engine_checked)]
        {
            total = total.checked_add(value).ok_or("overflow")?;
        }
        #[cfg(not(engine_checked))]
        {
            total = total.wrapping_add(value);
        }
    }
    Ok(total)
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn empty_and_small() {
        assert_eq!(sum(&[]), Ok(0));
        assert_eq!(sum(&[1, 2, 3]), Ok(6));
    }
    #[test]
    fn overflow_contract() {
        if cfg!(feature = "checked") {
            assert_eq!(sum(&[250, 10]), Err("overflow"));
            assert_eq!(MODE, "checked");
        } else {
            assert_eq!(sum(&[250, 10]), Ok(4));
