use std::{
    env,
    io::{self, Read, Write},
    net::{TcpListener, TcpStream},
    thread,
    time::Duration,
};
fn self_check() -> io::Result<()> {
    let listener = TcpListener::bind("127.0.0.1:0")?;
    let address = listener.local_addr()?;
    let mut client =
        TcpStream::connect_timeout(&address, Duration::from_secs(2))?;
    client.set_read_timeout(Some(Duration::from_secs(2)))?;
    let server =
        thread::spawn(move || bounded_http::serve(listener, 1));
    let result = (|| {
        client
            .write_all(b"GET / HTTP/1.1\r\nHost: localhost\r\n\r\n")?;
        let mut response = String::new();
        client.read_to_string(&mut response)?;
        if !response.starts_with("HTTP/1.1 200 OK\r\n")
            || !response.ends_with("Rust says hello.\n")
        {
            return Err(io::Error::other("unexpected response"));
        }
        Ok(())
    })();
    // Connection is already queued before spawning; on errors EOF wakes its reader.
    drop(client);
    server
        .join()
        .map_err(|_| io::Error::other("server panicked"))??;
    result?;
    println!("HTTP checks passed");
    Ok(())
}
fn main() -> io::Result<()> {
    let args: Vec<_> = env::args().skip(1).collect();
    if args == ["--self-check"] {
        return self_check();
    }
    if args != ["--requests", "2"] {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "use --self-check or --requests 2",
        ));
    }
    let listener = TcpListener::bind("127.0.0.1:7878")?;
    println!("Serving two connections at http://127.0.0.1:7878");
    bounded_http::serve(listener, 2)
}

