    fn rejects_non_utf8_and_oversized_headers() {
        assert!(
            text(&[255, 13, 10, 13, 10]).starts_with("HTTP/1.1 400")
        );
        assert!(
            text(&vec![b'x'; MAX_HEADER + 1])
                .starts_with("HTTP/1.1 400")
        );
    }
}

/// Recognizable HEAD requests never transmit bodies, including error replies.
pub fn reply(header: &[u8]) -> Vec<u8> {
    let mut result = reply_representation(header);
    let method = header
        .split(|b| b.is_ascii_whitespace())
        .find(|part| !part.is_empty());
    if method == Some(b"HEAD".as_slice()) {
        let end =
            result.windows(4).position(|w| w == b"\r\n\r\n").unwrap();
        result.truncate(end + 4);
    }
    result
}

use bounded_http::{
    http::{self, MAX_HEADER},
    serve,
};
use std::{
    io::{Read, Write},
    net::{Shutdown, TcpListener, TcpStream},
    thread,
    time::{Duration, Instant},
};
fn exchange(request: &[u8]) -> String {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let address = listener.local_addr().unwrap();
    let server = thread::spawn(move || serve(listener, 1).unwrap());
    let mut client =
        TcpStream::connect_timeout(&address, Duration::from_secs(2))
            .unwrap();
    client
        .set_read_timeout(Some(Duration::from_secs(2)))
        .unwrap();
    client.write_all(request).unwrap();
    client.shutdown(Shutdown::Write).unwrap();
    let mut response = String::new();
    client.read_to_string(&mut response).unwrap();
    server.join().unwrap();
    response
}
#[test]
fn actual_tcp_success_and_not_found() {
    assert!(
        exchange(b"GET / HTTP/1.1\r\nHost: x\r\n\r\n")
            .ends_with("Rust says hello.\n")
    );
    assert!(
        exchange(b"GET /missing HTTP/1.1\r\nHost: x\r\n\r\n")
            .starts_with("HTTP/1.1 404")
    );
}
#[test]
fn incomplete_header_hits_deadline() {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let address = listener.local_addr().unwrap();
    let server = thread::spawn(move || {
        let (mut stream, _) = listener.accept().unwrap();
        let start = Instant::now();
        assert!(
            http::read_header(&mut stream, Duration::from_millis(100))
                .is_err()
        );
        assert!(start.elapsed() < Duration::from_secs(2));
    });
    let mut client =
        TcpStream::connect_timeout(&address, Duration::from_secs(2))
            .unwrap();
    client.write_all(b"GET /").unwrap();
    server.join().unwrap();
    drop(client);
}
#[test]
fn actual_header_limit_is_enforced() {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let address = listener.local_addr().unwrap();
    let server = thread::spawn(move || {
        let (mut stream, _) = listener.accept().unwrap();
        let error =
            http::read_header(&mut stream, Duration::from_secs(1))
                .unwrap_err();
        assert_eq!(error.kind(), std::io::ErrorKind::InvalidData);
    });
    let mut client =
        TcpStream::connect_timeout(&address, Duration::from_secs(2))
            .unwrap();
    client.write_all(&vec![b'x'; MAX_HEADER]).unwrap();
    server.join().unwrap();
}

#[test]
fn header_spanning_multiple_reads() {
    let request = format!(
        "GET / HTTP/1.1\r\nHost: x\r\nX-Pad: {}\r\n\r\n",
        "a".repeat(1200)
    );
    assert!(exchange(request.as_bytes()).starts_with("HTTP/1.1 200"));
}
#[test]
fn drip_feed_does_not_reset_absolute_deadline() {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let address = listener.local_addr().unwrap();
    let mut client =
        TcpStream::connect_timeout(&address, Duration::from_secs(2))
            .unwrap();
    let server = thread::spawn(move || {
        let (mut stream, _) = listener.accept().unwrap();
        let start = Instant::now();
        assert!(
            http::read_header(&mut stream, Duration::from_millis(100))
                .is_err()
        );
        assert!(start.elapsed() < Duration::from_millis(800));
    });
    for _ in 0..40 {
        if client.write_all(b"x").is_err() {
            break;
        }
        thread::sleep(Duration::from_millis(30));
    }
    drop(client);
    server.join().unwrap();
}

#[test]
fn head_preserves_get_headers_without_body() {
    for path in ["/", "/missing"] {
        let get = exchange(
            format!("GET {path} HTTP/1.1\r\nHost: x\r\n\r\n")
                .as_bytes(),
        );
        let head = exchange(
            format!("HEAD {path} HTTP/1.1\r\nHost: x\r\n\r\n")
                .as_bytes(),
        );
        let (get_headers, _) = get.split_once("\r\n\r\n").unwrap();
        let (head_headers, body) = head.split_once("\r\n\r\n").unwrap();
        assert_eq!(get_headers, head_headers);
        assert!(body.is_empty());
    }
}

