fn head_validation_errors_have_no_body() {
    for tail in [
        "/ HTTP/1.1\r\n\r\n",
        "/ HTTP/1.1\r\nHost: x\r\nContent-Length: 1\r\n\r\n",
        "/ HTTP/1.0\r\nHost: x\r\n\r\n",
