use std::{ffi::OsString, path::PathBuf};
#[derive(Debug, PartialEq)]
pub struct Config {
    pub query: String,
    pub path: PathBuf,
}
impl Config {
    /// Input includes argv[0]. Consume only required fields and one extra check.
    pub fn parse(
        mut args: impl Iterator<Item = OsString>,
    ) -> Result<Self, &'static str> {
        args.next();
        let query = args
            .next()
            .ok_or("missing query")?
            .into_string()
            .map_err(|_| "query must be UTF-8")?;
        let path = PathBuf::from(args.next().ok_or("missing path")?);
        if args.next().is_some() {
            return Err("unexpected extra argument");
        }
        Ok(Self { query, path })
    }
}

pub fn search_lines<'text, 'query, I>(
    query: &'query str,
    lines: I,
) -> impl Iterator<Item = &'text str> + use<'text, 'query, I>
where
    I: Iterator<Item = &'text str>,
{
    lines.filter(move |line| line.contains(query))
}

pub fn search<'text>(query: &str, text: &'text str) -> Vec<&'text str> {
    search_lines(query, text.lines()).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::Cell;
    fn args(values: &[&str]) -> impl Iterator<Item = OsString> {
        values.iter().map(OsString::from)
    }
    #[test]
    fn parser_consumes_program_name_and_owned_fields() {
        assert_eq!(
            Config::parse(args(&["tool", "rust", "file.txt"])).unwrap(),
            Config {
                query: "rust".into(),
                path: "file.txt".into()
            }
        );
        assert_eq!(
            Config::parse(args(&[])).unwrap_err(),
            "missing query"
        );
        assert_eq!(
            Config::parse(args(&["tool"])).unwrap_err(),
            "missing query"
        );
        assert_eq!(
            Config::parse(args(&["tool", "rust"])).unwrap_err(),
            "missing path"
        );
    }
    #[test]
    fn parser_does_not_drain_an_unbounded_tail() {
        let count = Cell::new(0);
        let input = ["tool", "rust", "file"]
            .into_iter()
            .chain(std::iter::repeat("extra"))
            .inspect(|_| count.set(count.get() + 1))
            .map(OsString::from);
        assert_eq!(
            Config::parse(input).unwrap_err(),
            "unexpected extra argument"
        );
        assert_eq!(count.get(), 4);
    }
    #[test]
    fn adapter_only_visits_lines_when_polled() {
        let count = Cell::new(0);
        let lines = ["skip", "rust", "later rust"]
            .into_iter()
            .inspect(|_| count.set(count.get() + 1));
        let mut found = search_lines("rust", lines);
        assert_eq!(count.get(), 0);
        assert_eq!(found.next(), Some("rust"));
        assert_eq!(count.get(), 2);
        drop(found);
        assert_eq!(count.get(), 2);
    }
    #[test]
    fn collected_results_keep_original_lines() {
        let text = String::from(
            "Rust:\nsafe, productive.\nTrust me.\nDuct tape.\r\n",
        );
        assert_eq!(
            search("duct", &text).into_iter().collect::<Vec<_>>(),
            vec!["safe, productive."]
        );
        assert!(search("absent", &text).into_iter().next().is_none());
        assert_eq!(search("", "").into_iter().count(), 0);
    }
    #[cfg(unix)]
    #[test]
    fn non_unicode_query_is_fallible_but_path_is_native() {
        use std::os::unix::ffi::OsStringExt;
        let bad = OsString::from_vec(vec![255]);
        assert_eq!(
            Config::parse(
                ["tool".into(), bad.clone(), "file".into()].into_iter()
            )
            .unwrap_err(),
            "query must be UTF-8"
        );
        let config = Config::parse(
            ["tool".into(), "rust".into(), bad.clone()].into_iter(),
        )
        .unwrap();
        assert_eq!(config.path.as_os_str(), bad);
    }
}

use itergrep::{Config, search};
use std::{
    env, fs,
    io::{self, Write},
    process::ExitCode,
};
fn main() -> ExitCode {
    let config = match Config::parse(env::args_os()) {
        Ok(config) => config,
        Err(error) => {
            eprintln!("usage: itergrep QUERY FILE\n{error}");
            return ExitCode::from(2);
        }
    };
    let text = match fs::read_to_string(config.path) {
        Ok(text) => text,
        Err(error) => {
            eprintln!("read error: {error}");
            return ExitCode::FAILURE;
        }
    };
    let result = (|| -> io::Result<()> {
        let stdout = io::stdout();
        let mut output = stdout.lock();
        for line in search(&config.query, &text) {
            writeln!(output, "{line}")?;
        }
        output.flush()
    })();
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("write error: {error}");
            ExitCode::FAILURE
        }
    }
}

