use std::os::unix::{ffi::OsStrExt, fs::OpenOptionsExt};
use std::{
    fs::{self, File, OpenOptions},
    io::{self, Write},
    path::{Path, PathBuf},
    sync::atomic::{AtomicU64, Ordering},
};
static NEXT: AtomicU64 = AtomicU64::new(0);

#[derive(Debug)]
pub struct ReplaceError {
    pub published: bool,
    pub source: io::Error,
}
impl std::fmt::Display for ReplaceError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "published={}: {}", self.published, self.source)
    }
}
impl std::error::Error for ReplaceError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        Some(&self.source)
    }
}
struct Stage {
    path: Option<PathBuf>,
    file: Option<File>,
}
impl Drop for Stage {
    fn drop(&mut self) {
        drop(self.file.take());
        if let Some(path) = self.path.take() {
            let _ = fs::remove_file(path);
        }
    }
}
fn stage(parent: &Path) -> io::Result<Stage> {
    for _ in 0..128 {
        let id = NEXT.fetch_add(1, Ordering::Relaxed);
        let path = parent.join(format!(
            ".codetutor-stage-{}-{id}",
            std::process::id()
        ));
        match OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&path)
        {
            Ok(file) => {
                return Ok(Stage {
                    path: Some(path),
                    file: Some(file),
                });
            }
            Err(error)
                if error.kind() == io::ErrorKind::AlreadyExists =>
            {
                continue;
            }
            Err(error) => return Err(error),
        }
    }
    Err(io::Error::new(
        io::ErrorKind::AlreadyExists,
        "staging names exhausted",
    ))
}

/// Trusted local Unix directory; cleanup is best effort, not hostile-path safe.
pub fn replace_with<F>(
    destination: &Path,
    write: F,
) -> Result<(), ReplaceError>
where
    F: FnOnce(&mut File) -> io::Result<()>,
{
    replace_then(destination, write, |_| Ok(()))
}
fn replace_then<F, G>(
    destination: &Path,
    write: F,
    after_publish: G,
) -> Result<(), ReplaceError>
where
    F: FnOnce(&mut File) -> io::Result<()>,
    G: FnOnce(&Path) -> io::Result<()>,
{
    let before = |source| ReplaceError {
        published: false,
        source,
    };
    if destination.file_name().is_none() {
        return Err(before(io::Error::new(
            io::ErrorKind::InvalidInput,
            "destination needs a filename",
        )));
    }
    // Keep destination-name equivalence explicit in this Unix example.
    let name = destination.file_name().unwrap().as_bytes();
    if !name.is_ascii() {
        return Err(before(io::Error::new(
            io::ErrorKind::InvalidInput,
            "this example requires an ASCII destination basename",
        )));
    }
    let prefix = b".codetutor-stage-";
    if name
        .get(..prefix.len())
        .is_some_and(|head| head.eq_ignore_ascii_case(prefix))
    {
        return Err(before(io::Error::new(
            io::ErrorKind::InvalidInput,
            "destination uses the reserved staging namespace",
        )));
    }
    let parent = destination
        .parent()
        .filter(|p| !p.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."));
    let mut pending = stage(parent).map_err(before)?;
    let file = pending.file.as_mut().unwrap();
    write(file).map_err(before)?;
    file.flush().map_err(before)?;
    file.sync_all().map_err(before)?;
    drop(pending.file.take());
    fs::rename(pending.path.as_ref().unwrap(), destination)
        .map_err(before)?;
    pending.path = None; // Publication transferred the name; Drop must not remove it.
    after_publish(parent).map_err(|source| ReplaceError {
        published: true,
        source,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::os::unix::fs::PermissionsExt;
    struct Directory(PathBuf);
    impl Directory {
        fn new() -> Self {
            for _ in 0..128 {
                let path = std::env::temp_dir().join(format!(
                    "codetutor-replace-{}-{}",
                    std::process::id(),
                    NEXT.fetch_add(1, Ordering::Relaxed)
                ));
                match fs::create_dir(&path) {
                    Ok(()) => return Self(path),
                    Err(e)
                        if e.kind() == io::ErrorKind::AlreadyExists =>
                    {
                        continue;
                    }
                    Err(e) => panic!("{e}"),
                }
            }
            panic!("test directory names exhausted");
        }
        fn destination(&self) -> PathBuf {
            self.0.join("notes.txt")
        }
        fn no_stages(&self) -> bool {
            fs::read_dir(&self.0).unwrap().all(|entry| {
                !entry
                    .unwrap()
                    .file_name()
                    .to_string_lossy()
                    .starts_with(".codetutor-stage-")
            })
        }
    }
    impl Drop for Directory {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.0);
        }
    }
    #[test]
    fn replaces_bytes_and_cleans_stage() {
        let root = Directory::new();
        let destination = root.destination();
        fs::write(&destination, b"old").unwrap();
        replace_with(&destination, |file| file.write_all(b"new notes"))
            .unwrap();
        assert_eq!(fs::read(&destination).unwrap(), b"new notes");
        assert_eq!(
            fs::metadata(&destination).unwrap().permissions().mode()
                & 0o777,
            0o600
        );
        assert!(root.no_stages());
    }
    #[test]
    fn failed_preparation_preserves_original() {
        let root = Directory::new();
        let destination = root.destination();
        fs::write(&destination, b"old").unwrap();
        let error = replace_with(&destination, |file| {
            file.write_all(b"partial")?;
            Err(io::Error::new(
                io::ErrorKind::Other,
                "injected preparation failure",
            ))
        })
        .unwrap_err();
        assert!(!error.published);
        assert_eq!(fs::read(&destination).unwrap(), b"old");
        assert!(root.no_stages());
    }
    #[test]
    fn unwinding_cleanup_preserves_original() {
        let root = Directory::new();
        let destination = root.destination();
        fs::write(&destination, b"old").unwrap();
        let result = std::panic::catch_unwind(|| {
            let _ = replace_with(&destination, |file| {
                file.write_all(b"partial")?;
                panic!("injected panic");
            });
        });
        assert!(result.is_err());
        assert_eq!(fs::read(&destination).unwrap(), b"old");
        assert!(root.no_stages());
    }
    #[test]
    fn failed_rename_cleans_stage_without_deleting_directory() {
        let root = Directory::new();
        let destination = root.destination();
        fs::create_dir(&destination).unwrap();
        let error =
            replace_with(&destination, |file| file.write_all(b"new"))
                .unwrap_err();
        assert!(!error.published);
        assert!(destination.is_dir());
        assert!(root.no_stages());
    }
    #[test]
    fn post_publish_error_does_not_mean_rollback() {
        let root = Directory::new();
        let destination = root.destination();
        fs::write(&destination, b"old").unwrap();
        let error = replace_then(
            &destination,
            |file| file.write_all(b"new"),
            |_| {
                Err(io::Error::new(
                    io::ErrorKind::Other,
                    "injected directory-sync failure",
                ))
            },
        )
        .unwrap_err();
        assert!(error.published);
        assert_eq!(fs::read(&destination).unwrap(), b"new");
        assert!(root.no_stages());
    }
    #[test]
    fn missing_parent_fails_before_writer() {
        let root = Directory::new();
        let error =
            replace_with(&root.0.join("missing/notes.txt"), |_| {
                panic!("writer must not run")
            })
            .unwrap_err();
        assert!(!error.published);
        assert!(root.no_stages());
    }
}

