pub mod http;
pub mod pool;
use pool::Pool;
use std::{io, net::TcpListener};
/// Accept exactly `limit` connections, drain accepted jobs and join workers.
/// A full queue closes the rejected connection instead of blocking acceptance.
pub fn serve(listener: TcpListener, limit: usize) -> io::Result<()> {
    let pool = Pool::new(4, 8)?;
    for stream in listener.incoming().take(limit) {
        let stream = stream?;
        let _ = pool.try_execute(move || {
            let _ = http::handle(stream);
        });
    }
    drop(pool);
    Ok(())
}

use std::{
    io,
    panic::{AssertUnwindSafe, catch_unwind},
    sync::{
        Arc, Mutex,
        mpsc::{self, SyncSender, TrySendError},
    },
    thread::{self, JoinHandle},
};
type Job = Box<dyn FnOnce() + Send + 'static>;
#[derive(Debug, PartialEq, Eq)]
pub enum SubmitError {
    Full,
    Closed,
}
pub struct Pool {
    sender: Option<SyncSender<Job>>,
    workers: Vec<JoinHandle<()>>,
}
impl Pool {
    pub fn new(workers: usize, capacity: usize) -> io::Result<Self> {
        if !(1..=32).contains(&workers)
            || !(1..=256).contains(&capacity)
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "workers 1..32; queue 1..256",
            ));
        }
        let (sender, receiver) = mpsc::sync_channel::<Job>(capacity);
        let receiver = Arc::new(Mutex::new(receiver));
        let mut pool = Self {
            sender: Some(sender),
            workers: Vec::new(),
        };
        for id in 0..workers {
            let receiver = Arc::clone(&receiver);
            pool.workers.push(
                thread::Builder::new()
                    .name(format!("http-worker-{id}"))
                    .spawn(move || {
                        loop {
                            // Drop the receive guard BEFORE invoking arbitrary job code.
                            let received = {
                                match receiver.lock() {
                                    Ok(guard) => guard.recv(),
                                    Err(_) => return,
                                }
                            };
                            match received {
                                Ok(job) => {
                                    let _ = catch_unwind(
                                        AssertUnwindSafe(job),
                                    );
                                }
                                Err(_) => break,
                            }
                        }
                    })?,
            );
        }
        Ok(pool)
    }
    pub fn try_execute(
        &self,
        job: impl FnOnce() + Send + 'static,
    ) -> Result<(), SubmitError> {
        let sender = self.sender.as_ref().ok_or(SubmitError::Closed)?;
        sender.try_send(Box::new(job)).map_err(|error| match error {
            TrySendError::Full(_) => SubmitError::Full,
            TrySendError::Disconnected(_) => SubmitError::Closed,
        })
    }
}
impl Drop for Pool {
    fn drop(&mut self) {
        // Closing the final sender wakes recv after queued jobs drain.
        drop(self.sender.take());
        let current = thread::current().id();
        // On a worker, joining ANY peer could prevent this callback from
        // signaling that peer. Detach all handles and let the closed queue drain.
        if self
            .workers
            .iter()
            .any(|worker| worker.thread().id() == current)
        {
            return;
        }
        for worker in self.workers.drain(..) {
            let _ = worker.join();
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::{
        sync::atomic::{AtomicUsize, Ordering},
        time::Duration,
    };
    const WAIT: Duration = Duration::from_secs(2);
    #[test]
    fn rejects_invalid_limits() {
        assert!(Pool::new(0, 1).is_err());
        assert!(Pool::new(1, 0).is_err());
        assert!(Pool::new(33, 1).is_err());
    }
    #[test]
    fn jobs_overlap_without_holding_receiver_mutex() {
        let pool = Pool::new(2, 2).unwrap();
        let (started, events) = mpsc::channel();
        let mut releases = Vec::new();
        for _ in 0..2 {
            let (release, wait) = mpsc::channel();
            releases.push(release);
            let started = started.clone();
            pool.try_execute(move || {
                started.send(()).unwrap();
                let _ = wait.recv_timeout(WAIT);
            })
            .unwrap();
        }
        events.recv_timeout(WAIT).unwrap();
        events.recv_timeout(WAIT).unwrap();
        for release in releases {
            let _ = release.send(());
        }
        drop(pool);
    }
    #[test]
    fn rejects_full_queue_and_drains_accepted_jobs() {
        let pool = Pool::new(1, 1).unwrap();
        let (start, started) = mpsc::channel();
        let (release, wait) = mpsc::channel();
        let completed = Arc::new(AtomicUsize::new(0));
        let counter = completed.clone();
        pool.try_execute(move || {
            start.send(()).unwrap();
            let _ = wait.recv_timeout(WAIT);
            counter.fetch_add(1, Ordering::SeqCst);
        })
        .unwrap();
        started.recv_timeout(WAIT).unwrap();
        let counter = completed.clone();
        pool.try_execute(move || {
            counter.fetch_add(1, Ordering::SeqCst);
        })
        .unwrap();
        assert_eq!(pool.try_execute(|| {}), Err(SubmitError::Full));
        release.send(()).unwrap();
        drop(pool);
        assert_eq!(completed.load(Ordering::SeqCst), 2);
    }
    #[test]
    fn worker_survives_a_panicking_job() {
        let pool = Pool::new(1, 2).unwrap();
        let (sent, received) = mpsc::channel();
        pool.try_execute(|| panic!("exercise panic")).unwrap();
        pool.try_execute(move || {
            sent.send(()).unwrap();
        })
        .unwrap();
        received.recv_timeout(WAIT).unwrap();
        drop(pool);
    }
    #[test]
    fn worker_drop_does_not_join_a_dependent_peer() {
        let pool = Arc::new(Pool::new(2, 2).unwrap());
        let last = pool.clone();
        let (started, events) = mpsc::channel();
        let (release, wait) = mpsc::channel();
        let (notify, notification) = mpsc::channel();
        let (finished, completion) = mpsc::channel();
        let a_started = started.clone();
        pool.try_execute(move || {
            a_started.send(()).unwrap();
            let _ = wait.recv_timeout(WAIT);
            drop(last);
            let _ = notify.send(());
        })
        .unwrap();
        pool.try_execute(move || {
            started.send(()).unwrap();
            let signaled = notification.recv_timeout(WAIT).is_ok();
            let _ = finished.send(signaled);
        })
        .unwrap();
        events.recv_timeout(WAIT).unwrap();
        events.recv_timeout(WAIT).unwrap();
        drop(pool);
        release.send(()).unwrap();
        assert!(completion.recv_timeout(WAIT).unwrap());
    }
    #[test]
    fn final_owner_can_be_released_on_worker() {
        let pool = Arc::new(Pool::new(2, 2).unwrap());
        let weak = Arc::downgrade(&pool);
        let captured = pool.clone();
        let (release, wait) = mpsc::channel();
        let (done, finished) = mpsc::channel();
        pool.try_execute(move || {
            let _ = wait.recv_timeout(WAIT);
            drop(captured);
            done.send(()).unwrap();
        })
        .unwrap();
        drop(pool);
        release.send(()).unwrap();
        finished.recv_timeout(WAIT).unwrap();
        assert!(weak.upgrade().is_none());
    }
}

use std::{
    io::{self, Read, Write},
    net::TcpStream,
    time::{Duration, Instant},
};
pub const MAX_HEADER: usize = 8192;
const HELLO: &str = include_str!("../assets/hello.html");
const NOT_FOUND: &str = include_str!("../assets/404.html");
fn response(status: &str, body: &str, allow: bool) -> Vec<u8> {
    response_kind(status, body, allow, "text/plain; charset=utf-8")
}
fn response_kind(
    status: &str,
    body: &str,
    allow: bool,
    kind: &str,
) -> Vec<u8> {
    let allow = if allow { "Allow: GET, HEAD\r\n" } else { "" };
    format!("HTTP/1.1 {status}\r\nContent-Length: {}\r\nContent-Type: {kind}\r\nConnection: close\r\n{allow}\r\n{body}",body.len()).into_bytes()
}
/// This teaching subset uses one request per connection and never reads bodies.
fn reply_representation(header: &[u8], slow: impl FnOnce()) -> Vec<u8> {
    let bad = || response("400 Bad Request", "bad request\n", false);
    if header.len() > MAX_HEADER || !header.ends_with(b"\r\n\r\n") {
        return bad();
    }
    let Ok(text) = str::from_utf8(header) else {
        return bad();
    };
    let mut lines = text.split("\r\n");
    let request: Vec<_> =
        lines.next().unwrap_or("").split_whitespace().collect();
    if request.len() != 3
        || request[2] != "HTTP/1.1"
        || !request[1].starts_with('/')
    {
        return bad();
    }
    let mut hosts = 0;
    for line in lines {
        if line.is_empty() {
            break;
        }
        let Some((name, value)) = line.split_once(':') else {
            return bad();
        };
        if name.is_empty()
            || !name
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b == b'-')
            || value.bytes().any(|b| b < 32 && b != b'\t')
        {
            return bad();
        }
        if name.eq_ignore_ascii_case("host") {
            if value.trim().is_empty() {
                return bad();
            }
            hosts += 1;
        }
        if name.eq_ignore_ascii_case("transfer-encoding")
            || (name.eq_ignore_ascii_case("content-length")
                && value.trim() != "0")
        {
            return bad();
        }
    }
    if hosts != 1 {
        return bad();
    }
    if request[0] != "GET" && request[0] != "HEAD" {
        return response(
            "405 Method Not Allowed",
            "method not allowed\n",
            true,
        );
    }
    match request[1] {
        "/" => html_page("200 OK", "hello.html"),
        "/sleep" => {
            slow();
            html_page("200 OK", "hello.html")
        }
        _ => html_page("404 Not Found", "404.html"),
    }
}
pub fn read_header(
    stream: &mut TcpStream,
    budget: Duration,
) -> io::Result<Vec<u8>> {
    let deadline = Instant::now() + budget;
    let mut header = Vec::new();
    let mut chunk = [0u8; 512];
    loop {
        let remaining =
            deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err(io::Error::new(
                io::ErrorKind::TimedOut,
                "header deadline",
            ));
        }
        stream.set_read_timeout(Some(remaining))?;
        let capacity = (MAX_HEADER - header.len()).min(chunk.len());
        if capacity == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "header too large",
            ));
        }
        let n = stream.read(&mut chunk[..capacity])?;
        if n == 0 {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "incomplete header",
            ));
        }
        header.extend_from_slice(&chunk[..n]);
        if let Some(end) =
            header.windows(4).position(|w| w == b"\r\n\r\n")
        {
            header.truncate(end + 4);
            return Ok(header);
        }
    }
}
pub fn handle(mut stream: TcpStream) -> io::Result<()> {
    stream.set_write_timeout(Some(Duration::from_secs(1)))?;
