    assert!(missing.starts_with("HTTP/1.1 404"));
    assert!(missing.ends_with(include_str!("../assets/404.html")));
}
struct Release(Option<mpsc::Sender<()>>);
impl Drop for Release {
    fn drop(&mut self) {
        if let Some(sender) = self.0.take() {
            let _ = sender.send(());
        }
    }
}
fn compare(workers: usize) {
    let pool = Pool::new(workers, 8).unwrap();
    let (release_tx, release_rx) = mpsc::channel();
    // Declared after pool: unwinding releases the gate before joining workers.
    let release = Release(Some(release_tx));
    let (entered_tx, entered_rx) = mpsc::channel();
    let (slow_tx, slow_rx) = mpsc::channel();
    pool.try_execute(move || {
        let mut gate_ok = false;
        let response = http::reply_with_slow(
            b"GET /sleep HTTP/1.1\r\nHost: x\r\n\r\n",
            || {
                let _ = entered_tx.send(());
                gate_ok = release_rx
                    .recv_timeout(Duration::from_secs(5))
                    .is_ok();
            },
        );
        let status_ok = response.starts_with(b"HTTP/1.1 200");
        let _ = slow_tx.send((gate_ok, status_ok));
    })
    .unwrap();
    entered_rx.recv_timeout(Duration::from_secs(2)).unwrap();
    let (fast_tx, fast_rx) = mpsc::channel();
    pool.try_execute(move || {
        let _ = fast_tx
            .send(http::reply(b"GET / HTTP/1.1\r\nHost: x\r\n\r\n"));
    })
    .unwrap();
    if workers == 1 {
        assert!(matches!(
            fast_rx.try_recv(),
            Err(mpsc::TryRecvError::Empty)
        ));
        drop(release);
        assert!(
            fast_rx
                .recv_timeout(Duration::from_secs(2))
                .unwrap()
                .starts_with(b"HTTP/1.1 200")
        );
    } else {
        assert!(
            fast_rx
                .recv_timeout(Duration::from_secs(2))
                .unwrap()
                .starts_with(b"HTTP/1.1 200")
        );
        drop(release);
    }
    drop(pool);
    assert_eq!(slow_rx.recv().unwrap(), (true, true));
}
#[test]
fn one_worker_queues_fast_work_behind_slow_callback() {
    compare(1);
}
#[test]
fn two_workers_complete_fast_work_before_slow_release() {
    compare(2);
}

