    fn worker_drop_does_not_join_a_dependent_peer() {
        let pool = Arc::new(Pool::new(2, 2).unwrap());
        let last = pool.clone();
        let (started, events) = mpsc::channel();
        let (release, wait) = mpsc::channel();
        let (notify, notification) = mpsc::channel();
        let (finished, completion) = mpsc::channel();
        let a_started = started.clone();
        pool.try_execute(move || {
            a_started.send(()).unwrap();
            let _ = wait.recv_timeout(WAIT);
            drop(last);
            let _ = notify.send(());
        })
        .unwrap();
        pool.try_execute(move || {
            started.send(()).unwrap();
            let signaled = notification.recv_timeout(WAIT).is_ok();
            let _ = finished.send(signaled);
        })
        .unwrap();
        events.recv_timeout(WAIT).unwrap();
        events.recv_timeout(WAIT).unwrap();
        drop(pool);
        release.send(()).unwrap();
        assert!(completion.recv_timeout(WAIT).unwrap());
    }
    #[test]
    fn final_owner_can_be_released_on_worker() {
        let pool = Arc::new(Pool::new(2, 2).unwrap());
        let weak = Arc::downgrade(&pool);
        let captured = pool.clone();
        let (release, wait) = mpsc::channel();
        let (done, finished) = mpsc::channel();
        pool.try_execute(move || {
            let _ = wait.recv_timeout(WAIT);
            drop(captured);
            done.send(()).unwrap();
        })
        .unwrap();
        drop(pool);
        release.send(()).unwrap();
        finished.recv_timeout(WAIT).unwrap();
        assert!(weak.upgrade().is_none());
    }
