use std::{
    io::{self, Read},
    net::TcpStream,
    time::{Duration, Instant},
};
pub const MAX_HEADER: usize = 8192;
const HELLO: &str = include_str!("../assets/hello.html");
const NOT_FOUND: &str = include_str!("../assets/404.html");
fn response(status: &str, body: &str, allow: bool) -> Vec<u8> {
    response_kind(status, body, allow, "text/plain; charset=utf-8")
}
fn response_kind(
    status: &str,
    body: &str,
    allow: bool,
    kind: &str,
) -> Vec<u8> {
    let allow = if allow { "Allow: GET, HEAD\r\n" } else { "" };
    format!("HTTP/1.1 {status}\r\nContent-Length: {}\r\nContent-Type: {kind}\r\nConnection: close\r\n{allow}\r\n{body}",body.len()).into_bytes()
}
/// This teaching subset uses one request per connection and never reads bodies.
fn reply_representation(header: &[u8], slow: impl FnOnce()) -> Vec<u8> {
    let bad = || response("400 Bad Request", "bad request\n", false);
    if header.len() > MAX_HEADER || !header.ends_with(b"\r\n\r\n") {
        return bad();
    }
    let Ok(text) = str::from_utf8(header) else {
        return bad();
    };
    let mut lines = text.split("\r\n");
    let request: Vec<_> =
        lines.next().unwrap_or("").split_whitespace().collect();
    if request.len() != 3
        || request[2] != "HTTP/1.1"
        || !request[1].starts_with('/')
    {
        return bad();
    }
    let mut hosts = 0;
    for line in lines {
        if line.is_empty() {
            break;
        }
        let Some((name, value)) = line.split_once(':') else {
            return bad();
        };
        if name.is_empty()
            || !name
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b == b'-')
            || value.bytes().any(|b| b < 32 && b != b'\t')
        {
            return bad();
        }
        if name.eq_ignore_ascii_case("host") {
            if value.trim().is_empty() {
                return bad();
            }
            hosts += 1;
        }
        if name.eq_ignore_ascii_case("transfer-encoding")
            || (name.eq_ignore_ascii_case("content-length")
                && value.trim() != "0")
        {
            return bad();
        }
    }
    if hosts != 1 {
        return bad();
    }
    if request[0] != "GET" && request[0] != "HEAD" {
        return response(
            "405 Method Not Allowed",
            "method not allowed\n",
            true,
        );
    }
    match request[1] {
        "/" => html_page("200 OK", "hello.html"),
        "/sleep" => {
            slow();
            html_page("200 OK", "hello.html")
        }
        _ => html_page("404 Not Found", "404.html"),
    }
}
pub fn read_header(
    stream: &mut TcpStream,
    budget: Duration,
) -> io::Result<Vec<u8>> {
    let deadline = Instant::now() + budget;
    let mut header = Vec::new();
    let mut chunk = [0u8; 512];
    loop {
        let remaining =
            deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err(io::Error::new(
                io::ErrorKind::TimedOut,
                "header deadline",
            ));
        }
        stream.set_read_timeout(Some(remaining))?;
        let capacity = (MAX_HEADER - header.len()).min(chunk.len());
        if capacity == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "header too large",
            ));
        }
        let n = stream.read(&mut chunk[..capacity])?;
        if n == 0 {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "incomplete header",
            ));
        }
        header.extend_from_slice(&chunk[..n]);
        if let Some(end) =
            header.windows(4).position(|w| w == b"\r\n\r\n")
        {
            header.truncate(end + 4);
            return Ok(header);
        }
    }
}
pub fn handle(mut stream: TcpStream) -> io::Result<()> {
    stream.set_write_timeout(Some(Duration::from_secs(1)))?;
    let header = read_header(&mut stream, Duration::from_secs(1))?;
    crate::deadline::write_response(
        &mut stream,
        &reply(&header),
        Duration::from_secs(1),
    )
}
