use std::{
    io::{self, Write},
    net::TcpStream,
    time::{Duration, Instant},
};
trait TimedWrite: Write {
    fn set_remaining(&mut self, remaining: Duration) -> io::Result<()>;
}
impl TimedWrite for TcpStream {
    fn set_remaining(&mut self, remaining: Duration) -> io::Result<()> {
        self.set_write_timeout(Some(remaining))
    }
}
pub fn write_response(
    writer: &mut TcpStream,
    bytes: &[u8],
    budget: Duration,
) -> io::Result<()> {
    let started = Instant::now();
    write_elapsed(writer, bytes, budget, || started.elapsed())
}
fn write_elapsed(
    writer: &mut impl TimedWrite,
    mut bytes: &[u8],
    budget: Duration,
    mut elapsed: impl FnMut() -> Duration,
) -> io::Result<()> {
    while !bytes.is_empty() {
        let remaining = budget.saturating_sub(elapsed());
        if remaining.is_zero() {
            return Err(io::Error::new(
                io::ErrorKind::TimedOut,
                "response deadline",
            ));
        }
        writer.set_remaining(remaining)?;
        match writer.write(bytes) {
            Ok(0) => {
                return Err(io::Error::new(
                    io::ErrorKind::WriteZero,
                    "response made no progress",
                ));
            }
            Ok(count) => bytes = &bytes[count..],
            Err(error)
                if error.kind() == io::ErrorKind::Interrupted =>
            {
                continue;
            }
            Err(error) => return Err(error),
        }
    }
    if elapsed() > budget {
        return Err(io::Error::new(
            io::ErrorKind::TimedOut,
            "response completed after deadline",
        ));
    }
    Ok(())
}
