fn actual_stalled_receiver_exhausts_total_write_allowance() {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let client = TcpStream::connect_timeout(
        &listener.local_addr().unwrap(),
        Duration::from_secs(2),
    )
    .unwrap();
    let (mut server, _) = listener.accept().unwrap();
    server.set_nonblocking(true).unwrap();
    let chunk = [b'x'; 16_384];
    let prefill_deadline = Instant::now() + Duration::from_secs(1);
    let mut prefilled = 0;
    let mut blocked = false;
    while prefilled < 64 * 1_048_576
        && Instant::now() < prefill_deadline
    {
        let remaining = (64 * 1_048_576 - prefilled).min(chunk.len());
        match server.write(&chunk[..remaining]) {
            Ok(0) => panic!("prefill unexpectedly made no progress"),
            Ok(count) => prefilled += count,
            Err(error) if error.kind() == io::ErrorKind::WouldBlock => {
                blocked = true;
                break;
            }
            Err(error)
                if error.kind() == io::ErrorKind::Interrupted =>
            {
                continue;
            }
            Err(error) => panic!("prefill failed: {error}"),
        }
    }
    assert!(
        blocked,
        "No backpressure observed within capped prefill; this environment is inconclusive"
    );
    server.set_nonblocking(false).unwrap();
    let payload = vec![0u8; 16 * 1_048_576];
    let started = Instant::now();
    let error = write_response(
        &mut server,
        &payload,
        Duration::from_millis(50),
    )
    .unwrap_err();
    let elapsed = started.elapsed();
    assert!(matches!(
        error.kind(),
        io::ErrorKind::WouldBlock | io::ErrorKind::TimedOut
    ));
    assert!(
        elapsed < Duration::from_secs(2),
        "scoped local timeout regression exceeded two seconds"
    );
    println!(
        "backpressure: prefilled={prefilled} bytes, payload={} bytes, elapsed={} us, kind={:?}",
        payload.len(),
        elapsed.as_micros(),
        error.kind()
    );
    drop(client); // The peer deliberately remains open and unread through the write.
}

