#![cfg_attr(not(feature = "std"), no_std)]

#[cfg(feature = "alloc")]
extern crate alloc;

/// An inline FIFO that returns ownership when full.
///
/// ```
/// use nostd_ring::Ring;
/// let mut ring = Ring::<_, 2>::new();
/// assert_eq!(ring.push(7), Ok(()));
/// assert_eq!(ring.pop(), Some(7));
/// ```
///
/// A live element reference prevents mutation:
/// ```compile_fail
/// use nostd_ring::Ring;
/// let mut ring = Ring::<_, 2>::new();
/// ring.push(7).unwrap();
/// let first = ring.iter().next().unwrap();
/// ring.push(8).unwrap();
/// assert_eq!(*first, 7);
/// ```
pub struct Ring<T, const N: usize> {
    slots: [Option<T>; N],
    head: usize,
    len: usize,
}

impl<T, const N: usize> Ring<T, N> {
    pub const fn new() -> Self {
        Self {
            slots: [const { None }; N],
            head: 0,
            len: 0,
        }
    }
    pub const fn len(&self) -> usize {
        self.len
    }
    pub const fn capacity(&self) -> usize {
        N
    }
    pub const fn is_empty(&self) -> bool {
        self.len == 0
    }
    pub const fn is_full(&self) -> bool {
        self.len == N
    }

    // Caller establishes N > 0 and offset < N. Avoid head + offset overflow.
    fn physical(&self, offset: usize) -> usize {
        let until_end = N - self.head;
        if offset >= until_end {
            offset - until_end
        } else {
            self.head + offset
        }
    }
    pub fn push(&mut self, value: T) -> Result<(), T> {
        if self.is_full() {
            return Err(value);
        }
        let index = self.physical(self.len);
        self.slots[index] = Some(value);
        self.len += 1;
        Ok(())
    }
    pub fn pop(&mut self) -> Option<T> {
        if self.is_empty() {
            return None;
        }
        let value = self.slots[self.head].take();
        self.len -= 1;
        self.head = if self.head + 1 == N { 0 } else { self.head + 1 };
        value
    }
    fn pop_back(&mut self) -> Option<T> {
        if self.is_empty() {
            return None;
        }
        let index = self.physical(self.len - 1);
        self.len -= 1;
        self.slots[index].take()
    }
    pub fn clear(&mut self) {
        // pop advances the invariant before an element's destructor runs.
        while let Some(value) = self.pop() {
            drop(value);
        }
    }
    pub fn iter(&self) -> Iter<'_, T, N> {
        Iter {
            ring: self,
            front: 0,
            back: self.len,
        }
    }
    #[cfg(feature = "alloc")]
    pub fn into_vec(self) -> alloc::vec::Vec<T> {
        self.into_iter().collect()
    }
}
impl<T, const N: usize> Default for Ring<T, N> {
    fn default() -> Self {
        Self::new()
    }
}
impl<T: core::fmt::Debug, const N: usize> core::fmt::Debug for Ring<T, N> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.debug_list().entries(self.iter()).finish()
    }
}
pub struct Iter<'a, T, const N: usize> {
    ring: &'a Ring<T, N>,
    front: usize,
    back: usize,
}
impl<'a, T, const N: usize> Iterator for Iter<'a, T, N> {
    type Item = &'a T;
    fn next(&mut self) -> Option<Self::Item> {
        if self.front == self.back {
            return None;
        }
        let index = self.ring.physical(self.front);
        self.front += 1;
        self.ring.slots[index].as_ref()
    }
    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.back - self.front;
        (remaining, Some(remaining))
    }
}
impl<T, const N: usize> ExactSizeIterator for Iter<'_, T, N> {}
impl<T, const N: usize> core::iter::FusedIterator for Iter<'_, T, N> {}
pub struct IntoIter<T, const N: usize>(Ring<T, N>);
impl<T, const N: usize> Iterator for IntoIter<T, N> {
    type Item = T;
    fn next(&mut self) -> Option<T> {
        self.0.pop()
    }
    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.0.len, Some(self.0.len))
    }
}
impl<T, const N: usize> ExactSizeIterator for IntoIter<T, N> {}
impl<T, const N: usize> core::iter::FusedIterator for IntoIter<T, N> {}
impl<T, const N: usize> IntoIterator for Ring<T, N> {
    type Item = T;
    type IntoIter = IntoIter<T, N>;
    fn into_iter(self) -> Self::IntoIter {
        IntoIter(self)
    }
}
impl<'a, T, const N: usize> IntoIterator for &'a Ring<T, N> {
    type Item = &'a T;
    type IntoIter = Iter<'a, T, N>;
    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

impl<'a, T, const N: usize> DoubleEndedIterator for Iter<'a, T, N> {
    fn next_back(&mut self) -> Option<Self::Item> {
        if self.front == self.back {
            return None;
        }
        self.back -= 1;
        self.ring.slots[self.ring.physical(self.back)].as_ref()
    }
}
impl<T, const N: usize> DoubleEndedIterator for IntoIter<T, N> {
    fn next_back(&mut self) -> Option<Self::Item> {
        self.0.pop_back()
    }
}

