use std::{marker::PhantomData, ptr::NonNull, rc::Rc};

#[repr(C)]
#[derive(Default, Debug)]
pub struct Context {
    allocated: usize,
    released: usize,
}
#[repr(C)]
struct ForeignBuffer {
    _opaque: [u8; 0],
}
unsafe extern "C" {
    fn teacher_make(
        input: *const u8,
        len: usize,
        stats: *mut Context,
        out: *mut *mut ForeignBuffer,
    ) -> std::ffi::c_int;
    fn teacher_data(buffer: *const ForeignBuffer) -> *const u8;
    fn teacher_len(buffer: *const ForeignBuffer) -> usize;
    fn teacher_release(buffer: *mut ForeignBuffer);
}
#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    InvalidByte,
    Allocation,
    Contract,
}
/// Owns a C allocation and exclusively borrows its bookkeeping context.
///
/// The borrow prevents moving or dropping that context while C retains its address:
/// ```compile_fail
/// use foreign_buffer::Context;
/// let buffer = {
///     let mut context = Context::default();
///     context.make(b"hello").unwrap()
/// };
/// assert_eq!(buffer.as_bytes(), b"HELLO");
/// ```
///
/// A byte slice cannot outlive its foreign owner:
/// ```compile_fail
/// use foreign_buffer::Context;
/// let mut context = Context::default();
/// let bytes;
/// {
///     let buffer = context.make(b"hello").unwrap();
///     bytes = buffer.as_bytes();
/// }
/// assert_eq!(bytes, b"HELLO");
/// ```
///
/// Handles deliberately cannot move to another thread:
/// ```compile_fail
/// use foreign_buffer::Buffer;
/// fn requires_send<T: Send>() {}
/// requires_send::<Buffer<'static>>();
/// ```
pub struct Buffer<'a> {
    pointer: NonNull<ForeignBuffer>,
    context: PhantomData<&'a mut Context>,
    // This teaching C API is deliberately confined to the creating thread.
    thread: PhantomData<Rc<()>>,
}
impl Context {
    /// Append only after the foreign operation succeeds. Existing output survives
    /// an InvalidByte/Allocation error; a Rust allocation abort is not recoverable.
    pub fn append_upper(&mut self, input: &[u8], output: &mut Vec<u8>) -> Result<usize, Error> {
        let buffer = self.make(input)?;
        let bytes = buffer.as_bytes();
        let count = bytes.len();
        output.extend_from_slice(bytes);
        Ok(count)
    }
    pub fn counts(&self) -> (usize, usize) {
        (self.allocated, self.released)
    }
    pub fn make<'a>(&'a mut self, input: &[u8]) -> Result<Buffer<'a>, Error> {
        let mut out = std::ptr::null_mut();
        // SAFETY: declaration matches buffer.h on the supported native targets;
        // input is readable for len bytes for this synchronous call, out is writable,
        // and the returned lifetime keeps this context exclusively borrowed.
        let status = unsafe { teacher_make(input.as_ptr(), input.len(), self, &mut out) };
        match status {
            0 => Ok(Buffer {
                pointer: NonNull::new(out).ok_or(Error::Contract)?,
                context: PhantomData,
                thread: PhantomData,
            }),
            1 => Err(Error::InvalidByte),
            2 => Err(Error::Allocation),
            _ => Err(Error::Contract),
        }
        // The C contract requires out=NULL on every failure and owns its cleanup.
        // A wrapper cannot repair arbitrary foreign memory corruption.
    }
}
impl Buffer<'_> {
    pub fn as_bytes(&self) -> &[u8] {
        // SAFETY: this private non-null handle was created by teacher_make and
        // remains live until Drop. C stores initialized bytes and never retains input.
        let len = unsafe { teacher_len(self.pointer.as_ptr()) };
        if len == 0 {
            return &[];
        } // C permits a NULL empty data pointer.
        // SAFETY: C promises data is non-null, initialized, immutable and readable
        // for len bytes. Rust slice lifetime is bounded by this owning handle.
        unsafe { std::slice::from_raw_parts(teacher_data(self.pointer.as_ptr()), len) }
    }
}
impl Drop for Buffer<'_> {
    fn drop(&mut self) {
        // SAFETY: no Clone/raw ownership escape exists. Call the matching C
        // destructor once; never reconstruct a Rust Vec from a C allocation.
        unsafe { teacher_release(self.pointer.as_ptr()) }
    }
}

