use proc_macro::{Delimiter, Group, Ident, Literal, Punct, Spacing, Span, TokenStream, TokenTree};

type Diagnostic = (Span, String);

/// `compile_error!("message");` whose every token carries `span`, so rustc points at that source token.
fn spanned_error(span: Span, message: &str) -> TokenStream {
    let mut literal = Literal::string(message);
    literal.set_span(span);
    let mut group = Group::new(Delimiter::Parenthesis, TokenStream::from(TokenTree::Literal(literal)));
    group.set_span(span);
    let mut tokens = vec![
        TokenTree::Ident(Ident::new("compile_error", span)),
        TokenTree::Punct(Punct::new('!', Spacing::Alone)),
        TokenTree::Group(group),
        TokenTree::Punct(Punct::new(';', Spacing::Alone)),
    ];
    for token in &mut tokens {
        token.set_span(span);
    }
    tokens.into_iter().collect()
}

/// Retry a function that returns `Result` up to `times` attempts in total.
#[proc_macro_attribute]
pub fn retry(attr: TokenStream, item: TokenStream) -> TokenStream {
    match expand(attr, item.clone()) {
        Ok(expanded) => expanded,
        Err((span, message)) => {
            // Report the problem and keep the original item, so rustc does not add a cascade of
            // "cannot find function" errors on top of ours.
            let mut out = spanned_error(span, &message);
            out.extend(item);
            out
        }
    }
}

/// Parse `times = N`.
fn parse_times(attr: TokenStream) -> Result<u32, Diagnostic> {
    let mut tokens = attr.into_iter();
    let name = match tokens.next() {
        Some(TokenTree::Ident(ident)) => ident,
        Some(other) => return Err((other.span(), "expected `times = N`".into())),
        None => return Err((Span::call_site(), "expected `times = N`".into())),
    };
    if name.to_string() != "times" {
        return Err((name.span(), format!("unknown option `{name}`, expected `times`")));
    }
    match tokens.next() {
        Some(TokenTree::Punct(p)) if p.as_char() == '=' => {}
        Some(other) => return Err((other.span(), "expected `=` after `times`".into())),
        None => return Err((name.span(), "expected `= N` after `times`".into())),
    }
    let literal = match tokens.next() {
        Some(TokenTree::Literal(literal)) => literal,
        Some(other) => return Err((other.span(), "expected an integer literal".into())),
        None => return Err((name.span(), "expected an integer after `=`".into())),
    };
    let times: u32 = literal
        .to_string()
        .parse()
        .map_err(|_| (literal.span(), "times must be a positive integer literal".to_string()))?;
    if times == 0 {
        return Err((literal.span(), "times must be at least 1".into()));
    }
    if let Some(extra) = tokens.next() {
        return Err((extra.span(), "unexpected tokens after `times = N`".into()));
    }
    Ok(times)
}

fn expand(attr: TokenStream, item: TokenStream) -> Result<TokenStream, Diagnostic> {
    let times = parse_times(attr)?;
