use std::cell::Cell;
use std::marker::PhantomData;
use std::sync::{Arc, Mutex};
use std::thread;

fn assert_send<T: Send>() {}
fn assert_sync<T: Sync>() {}

/// A raw pointer is neither Send nor Sync; this wrapper takes responsibility for both.
struct Handle(*mut u64);

// SAFETY: a Handle is only created by `Owner::handle`, points into a heap allocation that outlives
// every use in this program, and at most one thread dereferences it at a time.
unsafe impl Send for Handle {}

struct Owner {
    value: Box<u64>,
}

impl Owner {
    fn handle(&mut self) -> Handle {
        Handle(&mut *self.value)
    }
}

/// Opting out: the marker contains a raw pointer, so the struct is neither Send nor Sync.
#[allow(dead_code)]
struct SingleThreaded(PhantomData<*const ()>);

fn main() {
    assert_send::<i32>();
    assert_sync::<i32>();
    assert_send::<String>();
    assert_sync::<String>();
    assert_send::<Arc<Mutex<Vec<u8>>>>();
    assert_sync::<Arc<Mutex<Vec<u8>>>>();
    assert_send::<Cell<i32>>(); // movable between threads...
    // assert_sync::<Cell<i32>>(); // ...but E0277: two threads could mutate through &Cell
    assert_send::<Mutex<Cell<i32>>>();
    assert_sync::<Mutex<Cell<i32>>>(); // the lock makes a !Sync type shareable
    println!("compile-time Send and Sync assertions passed");

    let total = Arc::new(Mutex::new(0u64));
    let workers: Vec<_> = (1..=4u64)
        .map(|n| {
            let total = Arc::clone(&total);
            thread::spawn(move || *total.lock().unwrap() += n * 100)
        })
        .collect();
    for worker in workers {
        worker.join().unwrap();
    }
    println!("Arc<Mutex<u64>> total = {}", total.lock().unwrap());

    let cell = Mutex::new(Cell::new(0));
    thread::scope(|s| {
        for _ in 0..3 {
            s.spawn(|| {
                let guard = cell.lock().unwrap();
                guard.set(guard.get() + 1);
            });
        }
    });
    println!("Mutex<Cell<i32>> shared by scoped threads = {}", cell.lock().unwrap().get());

    let mut owner = Owner { value: Box::new(0) };
    let handle = owner.handle();
    thread::scope(|s| {
        s.spawn(move || {
            let h = handle; // capture the whole Send wrapper, not just the raw pointer field
            // SAFETY: the pointee is alive, the owner is not touching it while this thread runs.
            unsafe { *h.0 += 41 };
        });
    });
    *owner.value += 1;
    println!("value updated through a Send handle = {}", owner.value);
}

