use std::marker::PhantomData;
use std::mem::size_of;

struct Order;
struct Trade;

/// A typed identifier: 4 bytes of data, and the type parameter exists only at compile time.
struct Id<T> {
    raw: u32,
    _marker: PhantomData<fn() -> T>,
}

// Manual impls: #[derive(Clone, Copy)] would demand T: Clone + Copy, which a marker does not need.
impl<T> Clone for Id<T> {
    fn clone(&self) -> Self {
        *self
    }
}
impl<T> Copy for Id<T> {}

impl<T> Id<T> {
    fn new(raw: u32) -> Self {
        Id { raw, _marker: PhantomData }
    }
}

fn cancel_order(id: Id<Order>) -> u32 {
    id.raw
}

fn trade_report(id: Id<Trade>) -> u32 {
    id.raw
}

fn assert_send_sync<T: Send + Sync>() {}

/// Covariance: a `&'static str` can be used where a shorter-lived `&'a str` is expected.
fn pick<'a>(long_lived: &'static str, short_lived: &'a str) -> &'a str {
    if long_lived.len() >= short_lived.len() { long_lived } else { short_lived }
}

/// `&mut &'a str` is invariant in 'a: the slot and the new value must agree on one lifetime.
fn set<'a>(slot: &mut &'a str, value: &'a str) {
    *slot = value;
}

fn main() {
    let order = Id::<Order>::new(7);
    let copy = order; // Copy works even though Order is not Copy
    println!("cancel {} then {} (still usable: Copy)", cancel_order(order), cancel_order(copy));
    println!("trade report {}", trade_report(Id::new(42)));
    // trade_report(order); // error: expected Id<Trade>, found Id<Order>
    println!("size_of::<Id<Order>>() = {}, size_of::<PhantomData<Order>>() = {}", size_of::<Id<Order>>(), size_of::<PhantomData<Order>>());
    assert_send_sync::<Id<std::rc::Rc<()>>>(); // fn() -> Rc<()> is Send + Sync, so the ID is too
    println!("Id<Rc<()>> is Send + Sync because the marker is fn() -> T");

    let local = String::from("short");
    println!("covariant pick: {}", pick("a much longer static string", &local));

    let mut slot: &str = "initial";
    let replacement = String::from("replacement");
    set(&mut slot, &replacement);
    println!("slot = {slot}");

    let f: fn(&str) -> usize = |s| s.len();
    let g: fn(&'static str) -> usize = f; // contravariance: accepts more, so usable where less is required
    println!("contravariant fn pointer: {}", g("four"));
}

