use std::mem::{align_of, size_of};
use std::ptr;
use std::slice;

fn split_at_mut_manual<T>(items: &mut [T], mid: usize) -> (&mut [T], &mut [T]) {
    let len = items.len();
    assert!(mid <= len, "mid out of range");
    let base = items.as_mut_ptr();
    // SAFETY: `base` is valid for `len` elements. [0, mid) and [mid, len) do not overlap and both lie
    // inside the original slice, and the exclusive borrow `items` lives as long as the results, so
    // nothing else can access these elements while the halves exist.
    unsafe { (slice::from_raw_parts_mut(base, mid), slice::from_raw_parts_mut(base.add(mid), len - mid)) }
}

#[repr(C, packed)]
struct Packed {
    tag: u8,
    value: u32,
}

fn main() {
    let mut data = [1, 2, 3, 4, 5, 6];
    let (left, right) = split_at_mut_manual(&mut data, 2);
    left[0] = 10;
    right[0] = 30;
    println!("after writing through both halves: {data:?}");
    let mut empty: [u8; 0] = [];
    let (a, b) = split_at_mut_manual(&mut empty, 0);
    println!("empty split: {} and {}", a.len(), b.len());

    let packed = Packed { tag: 7, value: 0xDEAD_BEEF };
    // `&packed.value` would be rejected (E0793): the field may be misaligned. addr_of! makes no reference.
    let pointer = ptr::addr_of!(packed.value);
    // SAFETY: the pointer is valid for reads of 4 bytes and read_unaligned has no alignment requirement.
    let value = unsafe { pointer.read_unaligned() };
    println!("packed field = {value:#x}, tag = {}, align = {}, size = {}", { packed.tag }, align_of::<Packed>(), size_of::<Packed>());

    // Tagging the low bits of a pointer, with provenance preserved by map_addr.
    let raw = Box::into_raw(Box::new(0xABCD_u64));
    assert_eq!(raw.addr() & 0b111, 0, "an 8-aligned pointer has three free low bits");
    let tagged = raw.map_addr(|address| address | 0b101);
    println!("tag stored in the pointer = {:#05b}", tagged.addr() & 0b111);
    let clean = tagged.map_addr(|address| address & !0b111);
    assert_eq!(clean, raw);
    // SAFETY: `clean` is the pointer from Box::into_raw with its original provenance, and it is freed once.
    let boxed = unsafe { Box::from_raw(clean) };
    println!("value through the cleaned pointer = {:#x}", *boxed);

    let numbers = [0u16; 8];
    let first = &numbers[1] as *const u16;
    let second = &numbers[6] as *const u16;
    // SAFETY: both pointers come from the same array, so the distance is defined.
    println!("offset_from within one array = {}", unsafe { second.offset_from(first) });
}

