use std::cell::RefCell;

/// A typed bump arena: allocation is a push, nothing is freed until the whole arena is dropped.
struct Arena<T> {
    chunks: RefCell<Vec<Vec<T>>>,
}

impl<T> Arena<T> {
    fn new() -> Self {
        Arena { chunks: RefCell::new(vec![Vec::with_capacity(4)]) }
    }

    /// Take `&self`, not `&mut self`, so earlier results stay usable while allocating more.
    fn alloc(&self, value: T) -> &mut T {
        let mut chunks = self.chunks.borrow_mut();
        let last = chunks.last().unwrap();
        if last.len() == last.capacity() {
            let next_capacity = last.capacity() * 2;
            chunks.push(Vec::with_capacity(next_capacity));
        }
        let chunk = chunks.last_mut().unwrap();
        chunk.push(value); // never reallocates: len < capacity was ensured above
        let slot: *mut T = chunk.last_mut().unwrap();
        // SAFETY: the element lives in a chunk whose buffer is never resized or moved (a full chunk is
        // left alone and a new one started), the outer Vec only moves chunk headers, each call returns
        // a different element so the &mut references never alias, and the arena owns the storage for
        // as long as the returned borrow of `self` lasts.
        unsafe { &mut *slot }
    }

    fn len(&self) -> usize {
        self.chunks.borrow().iter().map(Vec::len).sum()
    }

    fn chunk_capacities(&self) -> Vec<usize> {
        self.chunks.borrow().iter().map(Vec::capacity).collect()
    }
}

use std::cell::Cell;
use std::rc::Rc;

struct Node<'a> {
    value: i32,
    next: Cell<Option<&'a Node<'a>>>,
}

struct Noisy(Rc<Cell<usize>>);

impl Drop for Noisy {
    fn drop(&mut self) {
        self.0.set(self.0.get() + 1);
    }
}

fn main() {
    let arena: Arena<Node> = Arena::new();
    let a = arena.alloc(Node { value: 1, next: Cell::new(None) });
    let b = arena.alloc(Node { value: 2, next: Cell::new(None) });
    let c = arena.alloc(Node { value: 3, next: Cell::new(None) });
    a.next.set(Some(b));
    b.next.set(Some(c));

    for i in 0..1000 {
        arena.alloc(Node { value: 100 + i, next: Cell::new(None) });
    }
    println!("allocated {} nodes in chunks of capacity {:?}", arena.len(), arena.chunk_capacities());

