/// A handle to a slot. The generation makes stale handles detectable after the slot is reused.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
struct Key {
    index: u32,
    generation: u32,
}

struct Entry<T> {
    generation: u32,
    value: Option<T>,
    next_free: Option<u32>,
}

struct Slab<T> {
    entries: Vec<Entry<T>>,
    free_head: Option<u32>,
    len: usize,
}

impl<T> Slab<T> {
    fn new() -> Self {
        Slab { entries: Vec::new(), free_head: None, len: 0 }
    }

    fn insert(&mut self, value: T) -> Key {
        self.len += 1;
        if let Some(index) = self.free_head {
            let entry = &mut self.entries[index as usize];
            self.free_head = entry.next_free.take();
            entry.value = Some(value);
            return Key { index, generation: entry.generation };
        }
        self.entries.push(Entry { generation: 0, value: Some(value), next_free: None });
        Key { index: (self.entries.len() - 1) as u32, generation: 0 }
    }

    fn get(&self, key: Key) -> Option<&T> {
        let entry = self.entries.get(key.index as usize)?;
        if entry.generation == key.generation { entry.value.as_ref() } else { None }
    }

    fn get_mut(&mut self, key: Key) -> Option<&mut T> {
        let entry = self.entries.get_mut(key.index as usize)?;
        if entry.generation == key.generation { entry.value.as_mut() } else { None }
    }

    fn remove(&mut self, key: Key) -> Option<T> {
        let entry = self.entries.get_mut(key.index as usize)?;
        if entry.generation != key.generation {
            return None;
        }
        let value = entry.value.take()?;
        self.len -= 1;
        // A slot whose generation counter is exhausted is retired instead of reused, so a stale key
        // can never match a recycled slot after the counter wraps.
        if let Some(next) = entry.generation.checked_add(1) {
            entry.generation = next;
            entry.next_free = self.free_head;
            self.free_head = Some(key.index);
        }
        Some(value)
    }

    fn len(&self) -> usize {
        self.len
    }
}
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
}

use std::collections::HashMap;

fn main() {
    let mut slab = Slab::new();
    let a = slab.insert("order A");
    let b = slab.insert("order B");
    println!("a = {a:?}, b = {b:?}, len = {}", slab.len());
    println!("remove a -> {:?}", slab.remove(a));
    let c = slab.insert("order C");
    println!("c reuses slot {} with generation {}", c.index, c.generation);
    println!("stale key a -> {:?}", slab.get(a));
    println!("fresh key c -> {:?}", slab.get(c));
    println!("removing a stale key again -> {:?}", slab.remove(a));
    if let Some(order) = slab.get_mut(b) {
        *order = "order B (amended)";
    }
    println!("b -> {:?}", slab.get(b));
    println!("key from nowhere -> {:?}", slab.get(Key { index: 99, generation: 0 }));

    let mut slab: Slab<u64> = Slab::new();
    let mut model: HashMap<Key, u64> = HashMap::new();
    let mut live: Vec<Key> = Vec::new();
    let mut dead: Vec<Key> = Vec::new();
    let mut rng = Rng(0x51AB);
    for step in 0..5000u64 {
        match rng.next() % 3 {
            0 => {
                let key = slab.insert(step);
                assert!(model.insert(key, step).is_none(), "a live key was reissued");
                live.push(key);
            }
            1 if !live.is_empty() => {
                let key = live.swap_remove((rng.next() as usize) % live.len());
                assert_eq!(slab.remove(key), model.remove(&key));
                dead.push(key);
            }
            _ if !dead.is_empty() => {
                let key = dead[(rng.next() as usize) % dead.len()];
                assert_eq!(slab.get(key), None, "stale key must not resolve");
                assert_eq!(slab.remove(key), None);
            }
            _ => {}
        }
        assert_eq!(slab.len(), model.len());
    }
    for (&key, value) in &model {
        assert_eq!(slab.get(key), Some(value));
    }
    println!("matches the HashMap model over 5000 random operations with stale keys: true");
    println!("slots allocated {} for {} live values", slab.entries.len(), slab.len());
}

