trait Pricer {
    fn price(&self, x: i64) -> i64;
    fn set_scale(&mut self, scale: i64);
    fn boxed_clone(&self) -> Box<dyn Pricer>;
}

#[derive(Clone)]
struct Linear(i64);
#[derive(Clone)]
struct Table(Vec<i64>);

impl Pricer for Linear {
    fn price(&self, x: i64) -> i64 {
        self.0 * x
    }
    fn set_scale(&mut self, scale: i64) {
        self.0 = scale;
    }
    fn boxed_clone(&self) -> Box<dyn Pricer> {
        Box::new(self.clone())
    }
}

impl Pricer for Table {
    fn price(&self, x: i64) -> i64 {
        self.0.get(x as usize).copied().unwrap_or(0) * self.0.len() as i64
    }
    fn set_scale(&mut self, scale: i64) {
        self.0.iter_mut().for_each(|v| *v = scale);
    }
    fn boxed_clone(&self) -> Box<dyn Pricer> {
        Box::new(self.clone())
    }
}

impl Clone for Box<dyn Pricer> {
    fn clone(&self) -> Self {
        self.boxed_clone()
    }
}

fn main() {
    let mut originals: Vec<Box<dyn Pricer>> = vec![Box::new(Linear(2)), Box::new(Table(vec![1, 2, 3]))];
    let copies = originals.clone();
    for pricer in &mut originals {
        pricer.set_scale(10);
    }
    let before: Vec<i64> = copies.iter().map(|p| p.price(1)).collect();
    let after: Vec<i64> = originals.iter().map(|p| p.price(1)).collect();
    assert_eq!(before, vec![2, 6]);
    assert_eq!(after, vec![10, 30]);
    println!("clones keep their own state: {before:?} vs {after:?}");
}

