    values.as_ref().iter().sum()
}

fn hash_of<T: Hash + ?Sized>(value: &T) -> u64 {
    let mut hasher = DefaultHasher::new();
    value.hash(&mut hasher);
    hasher.finish()
}

fn label(cow: &Cow<str>) -> &'static str {
    if matches!(cow, Cow::Borrowed(_)) { "borrowed" } else { "owned" }
}

