struct Dedup<I: Iterator> {
    iter: I,
    last: Option<I::Item>,
}

impl<I: Iterator> Iterator for Dedup<I>
where
    I::Item: PartialEq + Clone,
{
    type Item = I::Item;

    fn next(&mut self) -> Option<I::Item> {
        loop {
            let item = self.iter.next()?;
            if self.last.as_ref() != Some(&item) {
                self.last = Some(item.clone());
                return Some(item);
            }
        }
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let (low, high) = self.iter.size_hint();
        // At least one item survives if any remain and nothing has been emitted yet; never more than the inner count.
        (usize::from(low > 0 && self.last.is_none()), high)
    }
}

trait DedupExt: Iterator + Sized {
    fn dedup(self) -> Dedup<Self>
    where
        Self::Item: PartialEq + Clone,
    {
        Dedup { iter: self, last: None }
    }
}

impl<I: Iterator> DedupExt for I {}

fn main() {
    let result: Vec<i32> = [1, 1, 2, 2, 2, 3, 1, 1].into_iter().dedup().collect();
    assert_eq!(result, vec![1, 2, 3, 1]);
    let mut state = 12345u64;
    for _ in 0..500 {
        let len = {
            state = state.wrapping_mul(6364136223846793005).wrapping_add(1);
            (state >> 60) as usize
        };
        let values: Vec<u8> = (0..len)
            .map(|_| {
                state = state.wrapping_mul(6364136223846793005).wrapping_add(1);
                (state >> 62) as u8
            })
            .collect();
        let mut expected = values.clone();
        expected.dedup();
        let it = values.iter().copied().dedup();
        let (low, high) = it.size_hint();
        let got: Vec<u8> = it.collect();
        assert_eq!(got, expected);
        assert!(low <= got.len() && high.is_none_or(|h| got.len() <= h));
    }
    println!("deduped: {result:?}; matches Vec::dedup and honours size_hint on 500 random vectors");
}

