use std::error::Error;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug, PartialEq)]
struct Order {
    buy: bool,
    qty: u32,
    symbol: String,
    price_cents: u64,
}

#[derive(Debug)]
#[non_exhaustive]
enum OrderError {
    MissingField(&'static str),
    UnknownSide(String),
    BadQuantity { text: String, source: ParseIntError },
    BadPrice { text: String, reason: &'static str },
}

impl fmt::Display for OrderError {
    // Display describes THIS error only; the cause is exposed through source() so reporters can print the chain.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            OrderError::MissingField(name) => write!(f, "missing field `{name}`"),
            OrderError::UnknownSide(side) => write!(f, "unknown side `{side}` (expected BUY or SELL)"),
            OrderError::BadQuantity { text, .. } => write!(f, "bad quantity `{text}`"),
            OrderError::BadPrice { text, reason } => write!(f, "bad price `{text}`: {reason}"),
        }
    }
}

impl Error for OrderError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            OrderError::BadQuantity { source, .. } => Some(source),
            _ => None,
        }
    }
}

#[derive(Debug)]
struct LineError {
    line: usize,
    source: OrderError,
}

impl fmt::Display for LineError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "line {}", self.line)
    }
}

impl Error for LineError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        Some(&self.source)
    }
}

fn parse_price(text: &str) -> Result<u64, OrderError> {
    let bad = |reason| OrderError::BadPrice { text: text.to_string(), reason };
    let (whole, cents) = text.split_once('.').unwrap_or((text, "00"));
    if cents.len() != 2 || !cents.bytes().all(|b| b.is_ascii_digit()) {
        return Err(bad("expected exactly two decimals"));
    }
    let whole: u64 = whole.parse().map_err(|_| bad("not a number"))?;
    Ok(whole * 100 + cents.parse::<u64>().unwrap())
}

fn parse_order(line: &str) -> Result<Order, OrderError> {
    let mut fields = line.split_whitespace();
    let side = fields.next().ok_or(OrderError::MissingField("side"))?;
    let buy = match side {
        "BUY" => true,
        "SELL" => false,
        other => return Err(OrderError::UnknownSide(other.to_string())),
    };
    let qty_text = fields.next().ok_or(OrderError::MissingField("quantity"))?;
    let qty = qty_text.parse().map_err(|source| OrderError::BadQuantity { text: qty_text.to_string(), source })?;
    let symbol = fields.next().ok_or(OrderError::MissingField("symbol"))?.to_string();
    let price_text = fields.next().ok_or(OrderError::MissingField("price"))?;
    Ok(Order { buy, qty, symbol, price_cents: parse_price(price_text)? })
}

fn load(text: &str) -> Result<Vec<Order>, LineError> {
    text.lines()
        .enumerate()
        .map(|(i, line)| parse_order(line).map_err(|source| LineError { line: i + 1, source }))
        .collect()
}

/// Print an error and every cause below it.
fn report(error: &dyn Error) -> String {
    let mut text = error.to_string();
    let mut cause = error.source();
    while let Some(inner) = cause {
        text.push_str(&format!(" <- caused by: {inner}"));
        cause = inner.source();
    }
    text
}

/// Number of causes below this error.
fn chain_depth(error: &dyn Error) -> usize {
    let mut depth = 0;
    let mut cause = error.source();
    while let Some(inner) = cause {
        depth += 1;
        cause = inner.source();
    }
    depth
}

fn run(text: &str) -> Result<u64, Box<dyn Error>> {
    let orders = load(text)?; // LineError converts into Box<dyn Error> through From
    Ok(orders.iter().map(|o| u64::from(o.qty) * o.price_cents).sum())
}

fn main() {
    let good = "BUY 100 AAPL 189.50\nSELL 50 MSFT 411.25";
    println!("parsed {} orders, notional cents = {}", load(good).unwrap().len(), run(good).unwrap());

    for (label, text) in [
        ("missing price", "BUY 100 AAPL"),
        ("bad side", "HOLD 100 AAPL 1.00"),
        ("bad quantity", "BUY 10 AAPL 1.00\nBUY abc AAPL 1.00"),
        ("bad price", "SELL 5 GOOG 142.1"),
    ] {
        let error = load(text).unwrap_err();
        println!("{label}: {}", report(&error));
    }

    let error = run("BUY 1 X 1.00\nBUY -1 X 1.00").unwrap_err();
    println!("through Box<dyn Error>: {}", report(error.as_ref()));
    match error.downcast_ref::<LineError>() {
        Some(line_error) => println!("downcast recovered the line number: {}", line_error.line),
        None => println!("not a LineError"),
    }

    let quantity_error = parse_order("BUY x A 1.00").unwrap_err();
    println!("source chain depth for a bad quantity: {}", chain_depth(&quantity_error));
    println!("a missing field has no source: {}", parse_order("BUY").unwrap_err().source().is_none());
}

