use std::fmt;

const SCALE: i64 = 10_000;

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
struct Money(i64);

#[derive(Debug, PartialEq)]
enum ParseError {
    Empty,
    BadDigit,
    TooManyDecimals,
    Overflow,
}

impl Money {
    fn parse(text: &str) -> Result<Money, ParseError> {
        let (negative, body) = match text.strip_prefix('-') {
            Some(rest) => (true, rest),
            None => (false, text),
        };
        let (whole, fraction) = body.split_once('.').unwrap_or((body, ""));
        if whole.is_empty() && fraction.is_empty() {
            return Err(ParseError::Empty);
        }
        if fraction.len() > 4 {
            return Err(ParseError::TooManyDecimals);
        }
        if !whole.bytes().chain(fraction.bytes()).all(|b| b.is_ascii_digit()) {
            return Err(ParseError::BadDigit);
        }
        let whole: i64 = if whole.is_empty() { 0 } else { whole.parse().map_err(|_| ParseError::Overflow)? };
        let mut fraction_units: i64 = if fraction.is_empty() { 0 } else { fraction.parse().unwrap() };
        for _ in fraction.len()..4 {
            fraction_units *= 10;
        }
        let units = whole.checked_mul(SCALE).and_then(|w| w.checked_add(fraction_units)).ok_or(ParseError::Overflow)?;
        Ok(Money(if negative { -units } else { units }))
    }

    fn checked_add(self, other: Money) -> Option<Money> {
        self.0.checked_add(other.0).map(Money)
    }

    fn times_qty(self, qty: i64) -> Option<Money> {
        self.0.checked_mul(qty).map(Money)
    }

    /// self * num / den, rounding half away from zero, with an i128 intermediate.
    fn scaled(self, num: i64, den: i64) -> Option<Money> {
        if den == 0 {
            return None;
        }
        let numerator = i128::from(self.0) * i128::from(num);
        let negative = (numerator < 0) != (den < 0);
        let (n, d) = (numerator.unsigned_abs(), i128::from(den).unsigned_abs());
        let magnitude = i64::try_from((2 * n + d) / (2 * d)).ok()?;
        Some(Money(if negative { -magnitude } else { magnitude }))
    }
}

impl fmt::Display for Money {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let sign = if self.0 < 0 { "-" } else { "" };
        let magnitude = self.0.unsigned_abs();
        write!(f, "{sign}{}.{:04}", magnitude / SCALE as u64, magnitude % SCALE as u64)
    }
}

fn main() {
    let price = Money::parse("19.99").unwrap();
    println!("parsed 19.99 -> {price}");
    let tenth = Money::parse("0.1").unwrap();
    let total = (0..10).try_fold(Money(0), |acc, _| acc.checked_add(tenth)).unwrap();
    println!("ten times 0.1 = {total}, equals 1: {}", total == Money::parse("1").unwrap());
    println!("19.99 * 3 = {}", price.times_qty(3).unwrap());

    for bad in ["", "1.23456", "1.2x", "999999999999999.9999"] {
        println!("parse {bad:?} -> {:?}", Money::parse(bad));
    }
    println!("max + 1 overflows: {}", Money(i64::MAX).checked_add(Money(1)).is_none());

    let hundred = Money::parse("100").unwrap();
    println!("100 / 3 = {}, 200 / 3 = {}", hundred.scaled(1, 3).unwrap(), hundred.scaled(2, 3).unwrap());
