use std::fmt;

#[derive(Clone, Copy, Debug, PartialEq)]
struct Money(i64);

impl fmt::Display for Money {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let sign = if self.0 < 0 { "-" } else { "" };
        let magnitude = self.0.unsigned_abs();
        write!(f, "{sign}{}.{:04}", magnitude / 10_000, magnitude % 10_000)
    }
}

fn vwap(fills: &[(Money, i64)]) -> Option<Money> {
    let notional: i128 = fills.iter().map(|(p, q)| i128::from(p.0) * i128::from(*q)).sum();
    let quantity: i128 = fills.iter().map(|(_, q)| i128::from(*q)).sum();
    if quantity == 0 {
        return None;
    }
    let negative = (notional < 0) != (quantity < 0);
    let (n, d) = (notional.unsigned_abs(), quantity.unsigned_abs());
    let magnitude = i64::try_from((2 * n + d) / (2 * d)).ok()?;
    Some(Money(if negative { -magnitude } else { magnitude }))
}

fn main() {
    let fills = [(Money(100_000), 100), (Money(105_000), 300)];
    assert_eq!(vwap(&fills), Some(Money(103_750)));
    assert_eq!(vwap(&[]), None);
    println!("vwap = {}", vwap(&fills).unwrap());
}

