fn quantize_buy(limit: i64, tick: i64) -> i64 {
    assert!(tick > 0);
    limit.div_euclid(tick) * tick
}

fn quantize_sell(limit: i64, tick: i64) -> i64 {
    assert!(tick > 0);
    let q = limit.div_euclid(tick);
    let r = limit.rem_euclid(tick);
    (if r == 0 { q } else { q + 1 }) * tick
}

fn main() {
    for tick in [1, 5, 25] {
        for limit in -200..=200 {
            let buy = quantize_buy(limit, tick);
            let sell = quantize_sell(limit, tick);
            assert!(buy <= limit && sell >= limit);
            assert!(buy % tick == 0 && sell % tick == 0);
            assert!(limit - buy < tick && sell - limit < tick);
            assert_eq!(quantize_buy(buy, tick), buy);
            assert_eq!(quantize_sell(sell, tick), sell);
        }
    }
    println!("limit 10037, tick 5: buy {}, sell {}", quantize_buy(10_037, 5), quantize_sell(10_037, 5));
}

