struct XorShift64Star(u64);

impl XorShift64Star {
    fn new(seed: u64) -> Self {
        assert!(seed != 0, "xorshift state must be non-zero");
        XorShift64Star(seed)
    }

    fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }

    fn next_f64(&mut self) -> f64 {
        (self.next_u64() >> 11) as f64 / (1u64 << 53) as f64
    }
}

/// splitmix64 turns (master seed, stream index) into a well-mixed non-zero seed.
fn stream_seed(master: u64, index: u64) -> u64 {
    let mut z = master.wrapping_add(index.wrapping_add(1).wrapping_mul(0x9E37_79B9_7F4A_7C15));
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    (z ^ (z >> 31)) | 1
}

fn estimate_pi(rng: &mut XorShift64Star, samples: u64) -> (f64, f64) {
    let mut hits = 0u64;
    for _ in 0..samples {
        let (x, y) = (rng.next_f64(), rng.next_f64());
        if x * x + y * y < 1.0 {
            hits += 1;
        }
    }
    let p = hits as f64 / samples as f64;
    (4.0 * p, 4.0 * (p * (1.0 - p) / samples as f64).sqrt())
}

fn main() {
    let mut a = XorShift64Star::new(12345);
    let mut b = XorShift64Star::new(12345);
    let mut c = XorShift64Star::new(54321);
    let first: Vec<u64> = (0..3).map(|_| a.next_u64()).collect();
    let same: Vec<u64> = (0..3).map(|_| b.next_u64()).collect();
    println!("same seed, same stream: {}", first == same);
    println!("different seed, different stream: {}", first[0] != c.next_u64());

    let mut rng = XorShift64Star::new(stream_seed(2026, 0));
    let samples = 1_000_000;
    let (pi, se) = estimate_pi(&mut rng, samples);
    println!("pi estimate = {pi:.5}, standard error = {se:.5}");
    println!("within 4 standard errors of pi: {}", (pi - std::f64::consts::PI).abs() < 4.0 * se);

    let mean_sq: f64 = (0..200_000).map(|_| { let u = rng.next_f64(); u * u }).sum::<f64>() / 200_000.0;
    println!("E[U^2] estimate = {mean_sq:.4} (exact 0.3333)");
    println!("independent stream seeds differ: {}", stream_seed(2026, 0) != stream_seed(2026, 1));
}

