    if !ticks.windows(2).all(|w| w[0].ts <= w[1].ts) {
        return Err("ticks must be sorted by timestamp");
    }
    let mut bars: Vec<Bar> = Vec::new();
    for tick in ticks {
        let start = tick.ts.div_euclid(interval) * interval;
        if bars.last().is_some_and(|b| b.start == start) {
            let bar = bars.last_mut().unwrap();
            bar.high = bar.high.max(tick.price);
            bar.low = bar.low.min(tick.price);
            bar.close = tick.price;
            bar.volume += u64::from(tick.qty);
            bar.ticks += 1;
            continue;
        }
        if let Some((prev_start, prev_close)) = bars.last().map(|b| (b.start, b.close)) {
            let mut gap = prev_start + interval;
            while gap < start {
                bars.push(Bar { start: gap, open: prev_close, high: prev_close, low: prev_close, close: prev_close, volume: 0, ticks: 0 });
                gap += interval;
            }
        }
        bars.push(Bar { start, open: tick.price, high: tick.price, low: tick.price, close: tick.price, volume: u64::from(tick.qty), ticks: 1 });
    }
    Ok(bars)
}

fn main() {
