        Tick { ts: SECOND * 9 / 10, price: 9_995, qty: 15 },
        Tick { ts: SECOND * 32 / 10, price: 10_050, qty: 30 },
        Tick { ts: SECOND * 39 / 10, price: 10_040, qty: 5 },
    ];
    let bars = resample(&ticks, SECOND).unwrap();
    println!("sec  open  high   low close vol ticks");
    for b in &bars {
        println!("{:>3} {:>5} {:>5} {:>5} {:>5} {:>3} {:>5}", b.start / SECOND, b.open, b.high, b.low, b.close, b.volume, b.ticks);
    }
    let synthetic = bars.iter().filter(|b| b.ticks == 0).count();
    println!("synthetic forward-filled bars: {synthetic}");
    println!("truncating division would put -0.5s in bucket {}", (-SECOND / 2) / SECOND);
    println!("div_euclid puts it in bucket {}", (-SECOND / 2).div_euclid(SECOND));
    let unsorted = [Tick { ts: 5, price: 1, qty: 1 }, Tick { ts: 1, price: 1, qty: 1 }];
    println!("unsorted input: {:?}", resample(&unsorted, SECOND).map(|b| b.len()));
}

