struct Tick {
    ts: i64,
    price: i64,
    qty: u32,
}

#[derive(Default)]
struct Bar {
    volume: u64,
    notional: i128,
}

fn vwap(bar: &Bar) -> Option<i64> {
    if bar.volume == 0 {
        return None;
    }
    let (n, d) = (bar.notional.unsigned_abs(), u128::from(bar.volume));
    let magnitude = i64::try_from((2 * n + d) / (2 * d)).ok()?;
    Some(if bar.notional < 0 { -magnitude } else { magnitude })
}

fn bar_for(ticks: &[Tick], start: i64, interval: i64) -> Bar {
    let mut bar = Bar::default();
    for t in ticks.iter().filter(|t| t.ts.div_euclid(interval) * interval == start) {
        bar.volume += u64::from(t.qty);
        bar.notional += i128::from(t.price) * i128::from(t.qty);
    }
    bar
}

fn main() {
    let ticks = [Tick { ts: 100, price: 10_000, qty: 10 }, Tick { ts: 400, price: 10_020, qty: 20 }];
    let bar = bar_for(&ticks, 0, 1_000);
    assert_eq!(vwap(&bar), Some(10_013));
    assert_eq!(vwap(&bar_for(&ticks, 1_000, 1_000)), None);
    println!("vwap = {:?}, empty bar = {:?}", vwap(&bar), vwap(&Bar::default()));
}

