use std::borrow::Cow;

#[derive(Debug, PartialEq)]
enum CsvError {
    UnterminatedQuote { line: usize },
    StrayQuote { line: usize, column: usize },
    WrongFieldCount { line: usize, expected: usize, found: usize },
}

/// Fields borrow from `line`; only a field containing "" needs an owned copy.
fn parse_line(line: &str, line_no: usize) -> Result<Vec<Cow<'_, str>>, CsvError> {
    let bytes = line.as_bytes();
    let mut fields = Vec::new();
    let mut i = 0;
    loop {
        if bytes.get(i) == Some(&b'"') {
            let start = i + 1;
            let mut j = start;
            let mut escaped = false;
            loop {
                match bytes.get(j) {
                    None => return Err(CsvError::UnterminatedQuote { line: line_no }),
                    Some(b'"') if bytes.get(j + 1) == Some(&b'"') => {
                        escaped = true;
                        j += 2;
                    }
                    Some(b'"') => break,
                    Some(_) => j += 1,
                }
            }
            let raw = &line[start..j];
            fields.push(if escaped { Cow::Owned(raw.replace("\"\"", "\"")) } else { Cow::Borrowed(raw) });
            i = j + 1;
            match bytes.get(i) {
                None => break,
                Some(b',') => i += 1,
                Some(_) => return Err(CsvError::StrayQuote { line: line_no, column: i + 1 }),
            }
        } else {
            let end = line[i..].find(',').map_or(line.len(), |p| i + p);
            let raw = &line[i..end];
            if let Some(p) = raw.find('"') {
                return Err(CsvError::StrayQuote { line: line_no, column: i + p + 1 });
            }
            fields.push(Cow::Borrowed(raw));
            if end == line.len() {
                break;
            }
            i = end + 1;
        }
    }
    Ok(fields)
}

fn parse_csv(text: &str) -> Result<Vec<Vec<Cow<'_, str>>>, CsvError> {
    let mut records = Vec::new();
    let mut expected = None;
    for (index, line) in text.lines().enumerate() {
        let fields = parse_line(line, index + 1)?;
        match expected {
            None => expected = Some(fields.len()),
            Some(n) if n != fields.len() => {
                return Err(CsvError::WrongFieldCount { line: index + 1, expected: n, found: fields.len() });
            }
            Some(_) => {}
        }
        records.push(fields);
    }
    Ok(records)
}

fn main() {
    let text = "symbol,note,price\nAAPL,\"split, adjusted\",189.5\nMSFT,\"said \"\"buy\"\"\",411.25\nGOOG,plain,142.1\n";
    let records = parse_csv(text).unwrap();
    println!("records = {}", records.len());
    let fields: Vec<&Cow<str>> = records.iter().flatten().collect();
    let borrowed = fields.iter().filter(|f| matches!(f, Cow::Borrowed(_))).count();
    println!("fields = {}, borrowed = {borrowed}, owned = {}", fields.len(), fields.len() - borrowed);
    println!("row 2 note = {:?}", records[1][1]);
    println!("row 3 note = {:?}", records[2][1]);

    let start = text.as_ptr() as usize;
    let inside = fields.iter().filter(|f| matches!(f, Cow::Borrowed(s) if (start..start + text.len()).contains(&(s.as_ptr() as usize)))).count();
    println!("borrowed fields that point into the input buffer: {inside}");

    println!("{:?}", parse_line("\"abc", 7));
    println!("{:?}", parse_line("ab\"c", 8));
    println!("{:?}", parse_line("\"ab\"c", 9));
    println!("{:?}", parse_line("a,", 10).map(|f| f.len()));
    println!("{:?}", parse_csv("a,b\n1,2,3\n"));
}

