fn round_all(values: impl IntoIterator<Item = f64>) -> Vec<f64> {
    values.into_iter().map(|v| (v * 10_000.0).round() / 10_000.0).collect()
}

/// Correlation matrix from a covariance matrix: cov[i][j] / (sd[i] * sd[j]).
fn correlation(cov: &Array2<f64>) -> Array2<f64> {
    let sd = cov.diag().mapv(f64::sqrt);
    Array2::from_shape_fn(cov.dim(), |(i, j)| cov[[i, j]] / (sd[i] * sd[j]))
}

fn main() {
    let data = array![[1.0, 2.0], [2.0, 4.0], [3.0, 5.0], [4.0, 4.0], [5.0, 5.0]];
    println!("shape = {:?}", data.dim());

    let first_column = data.slice(s![.., 0]); // a view: no copy
    let last_two = data.slice(s![3.., ..]);
    println!("column 0 view = {first_column}, sum = {}", first_column.sum());
    println!("last two rows = {last_two}");

    let cov = covariance(&data);
    println!("covariance = {cov}");

    let matrix = DMatrix::from_row_slice(2, 2, cov.as_slice().expect("standard layout"));
    let eigen = SymmetricEigen::new(matrix);
    let mut values: Vec<f64> = eigen.eigenvalues.iter().copied().collect();
    values.sort_by(f64::total_cmp);
    println!("eigenvalues = {:?}", round_all(values));

    // Least squares y = a + b x. SVD handles rectangular and rank-deficient systems.
    let x = DMatrix::from_row_slice(4, 2, &[1.0, 0.0, 1.0, 1.0, 1.0, 2.0, 1.0, 3.0]);
    let y = DVector::from_row_slice(&[1.0, 3.0, 5.0, 7.0]);
    let beta = x.svd(true, true).solve(&y, 1e-12).expect("svd computed U and V");
    println!("fit = {:?}", round_all(beta.iter().copied()));
