fn sum_scalar(values: &[i32]) -> i32 {
    values.iter().sum()
}

#[cfg(target_arch = "aarch64")]
fn sum_fast(values: &[i32]) -> i32 {
    use std::arch::aarch64::{vaddq_s32, vaddvq_s32, vdupq_n_s32, vld1q_s32};
    let chunks = values.len() / 4;
    // SAFETY: loads cover indices 0..4 * chunks, which is within the slice.
    let mut total = unsafe {
        let mut acc = vdupq_n_s32(0);
        for i in 0..chunks {
            acc = vaddq_s32(acc, vld1q_s32(values.as_ptr().add(i * 4)));
        }
        vaddvq_s32(acc)
    };
    for v in &values[chunks * 4..] {
        total += v;
    }
    total
}

#[cfg(not(target_arch = "aarch64"))]
fn sum_fast(values: &[i32]) -> i32 {
    sum_scalar(values)
}

