use std::thread;

fn chunk_len(len: usize, parts: usize) -> usize {
    len.div_ceil(parts).max(1)
}

fn parallel_sum(data: &[u64], parts: usize) -> u64 {
    thread::scope(|s| {
        let handles: Vec<_> = data
            .chunks(chunk_len(data.len(), parts))
            .map(|part| s.spawn(move || part.iter().sum::<u64>()))
            .collect();
        handles.into_iter().map(|h| h.join().unwrap()).sum()
    })
}

fn parallel_square(data: &mut [u64], parts: usize) {
    let size = chunk_len(data.len(), parts);
    thread::scope(|s| {
        for part in data.chunks_mut(size) {
            s.spawn(move || {
                for v in part.iter_mut() {
                    *v *= *v;
                }
            });
        }
    });
}

fn parallel_sum_f64(data: &[f64], parts: usize) -> f64 {
    thread::scope(|s| {
        let handles: Vec<_> = data
            .chunks(chunk_len(data.len(), parts))
            .map(|part| s.spawn(move || part.iter().sum::<f64>()))
            .collect();
        // Combine in chunk order so the result does not depend on thread timing.
        handles.into_iter().map(|h| h.join().unwrap()).fold(0.0, |a, b| a + b)
    })
}

fn main() {
    let mut data: Vec<u64> = (1..=1000).collect();
    let serial: u64 = data.iter().sum();
    for parts in [1, 2, 3, 4, 7] {
        assert_eq!(parallel_sum(&data, parts), serial);
    }
    println!("sum = {serial}");
    parallel_square(&mut data, 4);
    println!("sum of squares = {}", data.iter().sum::<u64>());

    let floats: Vec<f64> = (1..=1000).map(|i| 1.0 / i as f64).collect();
    let first = parallel_sum_f64(&floats, 4);
    let second = parallel_sum_f64(&floats, 4);
    assert_eq!(first.to_bits(), second.to_bits());
    println!("repeatable with a fixed chunk order: true");
    println!("empty slice sum = {}", parallel_sum(&[], 4));
}

