use std::cell::UnsafeCell;
use std::mem::MaybeUninit;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

struct Shared<T> {
    buffer: Box<[UnsafeCell<MaybeUninit<T>>]>,
    mask: usize,
    head: AtomicUsize,
    tail: AtomicUsize,
}

// SAFETY: a slot is written only by the single Producer and read only by the
// single Consumer, and ownership of a slot is handed over through head/tail
// with Release stores and Acquire loads. T: Send lets values cross threads.
unsafe impl<T: Send> Sync for Shared<T> {}

impl<T> Drop for Shared<T> {
    fn drop(&mut self) {
        let mut head = *self.head.get_mut();
        let tail = *self.tail.get_mut();
        while head != tail {
            // SAFETY: slots in head..tail were written and never read out.
            unsafe { self.buffer[head & self.mask].get_mut().assume_init_drop() };
            head = head.wrapping_add(1);
        }
    }
}

struct Producer<T> {
    shared: Arc<Shared<T>>,
}

struct Consumer<T> {
    shared: Arc<Shared<T>>,
}

fn channel<T>(capacity: usize) -> (Producer<T>, Consumer<T>) {
    let capacity = capacity.next_power_of_two();
    let buffer = (0..capacity).map(|_| UnsafeCell::new(MaybeUninit::uninit())).collect();
    let shared = Arc::new(Shared { buffer, mask: capacity - 1, head: AtomicUsize::new(0), tail: AtomicUsize::new(0) });
    (Producer { shared: shared.clone() }, Consumer { shared })
}

impl<T> Producer<T> {
    fn capacity(&self) -> usize {
        self.shared.mask + 1
    }

    fn push(&mut self, value: T) -> Result<(), T> {
        let tail = self.shared.tail.load(Ordering::Relaxed);
        let head = self.shared.head.load(Ordering::Acquire);
        if tail.wrapping_sub(head) == self.capacity() {
            return Err(value);
        }
        // SAFETY: the queue is not full, so the consumer is not reading this slot.
        unsafe { (*self.shared.buffer[tail & self.shared.mask].get()).write(value) };
        self.shared.tail.store(tail.wrapping_add(1), Ordering::Release);
        Ok(())
    }
}

impl<T> Consumer<T> {
    fn pop(&mut self) -> Option<T> {
        let head = self.shared.head.load(Ordering::Relaxed);
        let tail = self.shared.tail.load(Ordering::Acquire);
        if head == tail {
            return None;
        }
        // SAFETY: head != tail, so this slot was initialised by the producer
        // and its write is visible through the Acquire load of tail.
        let value = unsafe { (*self.shared.buffer[head & self.shared.mask].get()).assume_init_read() };
        self.shared.head.store(head.wrapping_add(1), Ordering::Release);
        Some(value)
    }
}

struct Noisy(Arc<AtomicUsize>);

impl Drop for Noisy {
    fn drop(&mut self) {
        self.0.fetch_add(1, Ordering::Relaxed);
    }
}

fn main() {
    let (mut tx, mut rx) = channel::<u64>(8);
    println!("capacity = {}", tx.capacity());
    for i in 0..8 {
        assert!(tx.push(i).is_ok());
    }
    assert_eq!(tx.push(99), Err(99));
    assert_eq!(rx.pop(), Some(0));
    assert!(tx.push(8).is_ok());
    let drained: Vec<u64> = std::iter::from_fn(|| rx.pop()).collect();
    println!("drained after wrap-around = {drained:?}");

    let (mut tx, mut rx) = channel::<u64>(64);
    let total = 100_000u64;
    let sum = thread::scope(|s| {
        s.spawn(move || {
            for i in 0..total {
                let mut value = i;
                while let Err(back) = tx.push(value) {
                    value = back;
                    thread::yield_now();
                }
            }
        });
        s.spawn(move || {
            let (mut expected, mut sum) = (0u64, 0u64);
            while expected < total {
                match rx.pop() {
                    Some(value) => {
                        assert_eq!(value, expected);
                        expected += 1;
                        sum += value;
                    }
                    None => thread::yield_now(),
                }
            }
            sum
        })
        .join()
        .unwrap()
    });
    println!("two-thread FIFO sum = {sum}");

    let drops = Arc::new(AtomicUsize::new(0));
    let (mut tx, mut rx) = channel::<Noisy>(4);
    for _ in 0..3 {
        tx.push(Noisy(drops.clone())).ok().unwrap();
    }
    drop(rx.pop());
    println!("drops after one pop = {}", drops.load(Ordering::Relaxed));
    drop(tx);
    drop(rx);
    println!("drops after both ends are gone = {}", drops.load(Ordering::Relaxed));
}

