use crossbeam_channel::bounded;
use rayon::prelude::*;
use std::thread;

fn sum_of_squares(values: &[u64]) -> u64 {
    values.par_iter().map(|v| v * v).sum()
}

fn best_price(prices: &[i64]) -> Option<i64> {
    prices.par_iter().copied().max()
}

/// Fixed chunks, combined in index order: reproducible whatever the thread count.
fn chunked_float_sum(values: &[f64]) -> f64 {
    let partials: Vec<f64> = values.par_chunks(250).map(|chunk| chunk.iter().sum()).collect();
    partials.iter().sum()
}

fn serial_chunked_float_sum(values: &[f64]) -> f64 {
    values.chunks(250).map(|chunk| chunk.iter().sum::<f64>()).sum()
}

/// Producer -> three workers -> consumer, joined by bounded channels.
fn pipeline(count: u64) -> (u64, u64) {
    let (raw_tx, raw_rx) = bounded::<u64>(16);
    let (out_tx, out_rx) = bounded::<u64>(16);
    thread::scope(|scope| {
        scope.spawn(move || {
            for i in 0..count {
                raw_tx.send(i).unwrap();
            }
            // raw_tx is dropped here, which closes the channel for the workers.
        });
        for _ in 0..3 {
            let rx = raw_rx.clone();
            let tx = out_tx.clone();
            scope.spawn(move || {
                for value in rx {
                    tx.send(value * 2).unwrap();
                }
            });
        }
        drop(raw_rx);
        drop(out_tx); // the consumer loop ends once every worker clone is gone too
        let (mut total, mut items) = (0, 0);
        for value in out_rx {
            total += value;
            items += 1;
        }
        (total, items)
    })
}

fn main() {
    let values: Vec<u64> = (1..=10_000).collect();
    println!("sum of squares = {}", sum_of_squares(&values));

    let prices: Vec<i64> = (0..5000).map(|i| (i * 7919) % 10_007 - 5000).collect();
    println!("best price = {:?}", best_price(&prices));

    let floats: Vec<f64> = (1..=1000).map(|i| 1.0 / f64::from(i)).collect();
    let pool = rayon::ThreadPoolBuilder::new().num_threads(2).build().unwrap();
    let in_pool = pool.install(|| (rayon::current_num_threads(), chunked_float_sum(&floats)));
    println!("pool threads = {}", in_pool.0);
    println!("parallel chunked sum matches serial chunked sum bit for bit: {}", in_pool.1.to_bits() == serial_chunked_float_sum(&floats).to_bits());

    let (total, items) = pipeline(1000);
    println!("pipeline total = {total} from {items} items");
}

