const CANCEL_LEN: usize = 21;

struct FrameReader {
    buffer: Vec<u8>,
}

impl FrameReader {
    fn new() -> Self {
        FrameReader { buffer: Vec::new() }
    }

    fn push(&mut self, chunk: &[u8]) {
        self.buffer.extend_from_slice(chunk);
    }

    fn next_cancel(&mut self) -> Option<(u64, u64, u32)> {
        if self.buffer.len() < CANCEL_LEN {
            return None;
        }
        assert_eq!(self.buffer[0], b'X', "stream is corrupt");
        let ts = u64::from_be_bytes(self.buffer[1..9].try_into().unwrap());
        let id = u64::from_be_bytes(self.buffer[9..17].try_into().unwrap());
        let shares = u32::from_be_bytes(self.buffer[17..21].try_into().unwrap());
        self.buffer.drain(..CANCEL_LEN);
        Some((ts, id, shares))
    }
}

fn encode_cancel(ts: u64, id: u64, shares: u32) -> Vec<u8> {
    let mut frame = vec![b'X'];
    frame.extend(ts.to_be_bytes());
    frame.extend(id.to_be_bytes());
    frame.extend(shares.to_be_bytes());
    frame
}

fn main() {
    let expected: Vec<(u64, u64, u32)> = (1..=4).map(|i| (i * 100, i, 10 * i as u32)).collect();
    let stream: Vec<u8> = expected.iter().flat_map(|&(ts, id, shares)| encode_cancel(ts, id, shares)).collect();
    let mut reader = FrameReader::new();
    let mut seen = Vec::new();
    for chunk in stream.chunks(7) {
        reader.push(chunk);
        while let Some(cancel) = reader.next_cancel() {
            seen.push(cancel);
        }
    }
    assert_eq!(seen, expected);
    println!("{} cancels recovered from {} chunks, {} bytes left", seen.len(), stream.chunks(7).count(), reader.buffer.len());
}

