use std::collections::{BTreeMap, HashMap, VecDeque};

type Price = i64;
type OrderId = u64;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Side {
    Bid,
    Ask,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Order {
    id: OrderId,
    qty: u32,
}

#[derive(Default)]
struct Level {
    orders: VecDeque<Order>,
    total: u64,
}

#[derive(Debug, PartialEq)]
enum BookError {
    DuplicateId,
    ZeroQuantity,
    WouldCross,
}

#[derive(Default)]
struct Book {
    bids: BTreeMap<Price, Level>,
    asks: BTreeMap<Price, Level>,
    index: HashMap<OrderId, (Side, Price)>,
}

impl Book {
    fn best_bid(&self) -> Option<(Price, u64)> {
        self.bids.last_key_value().map(|(p, l)| (*p, l.total))
    }

    fn best_ask(&self) -> Option<(Price, u64)> {
        self.asks.first_key_value().map(|(p, l)| (*p, l.total))
    }

    fn add(&mut self, id: OrderId, side: Side, price: Price, qty: u32) -> Result<(), BookError> {
        if qty == 0 {
            return Err(BookError::ZeroQuantity);
        }
        if self.index.contains_key(&id) {
            return Err(BookError::DuplicateId);
        }
        let crosses = match side {
            Side::Bid => self.best_ask().is_some_and(|(ask, _)| price >= ask),
            Side::Ask => self.best_bid().is_some_and(|(bid, _)| price <= bid),
        };
        if crosses {
            return Err(BookError::WouldCross);
        }
        let levels = if side == Side::Bid { &mut self.bids } else { &mut self.asks };
        let level = levels.entry(price).or_default();
        level.orders.push_back(Order { id, qty });
        level.total += u64::from(qty);
        self.index.insert(id, (side, price));
        Ok(())
    }

    fn cancel(&mut self, id: OrderId) -> Option<Order> {
        let (side, price) = self.index.remove(&id)?;
        let levels = if side == Side::Bid { &mut self.bids } else { &mut self.asks };
        let level = levels.get_mut(&price)?;
        let position = level.orders.iter().position(|o| o.id == id)?;
        let order = level.orders.remove(position)?;
        level.total -= u64::from(order.qty);
        if level.orders.is_empty() {
            levels.remove(&price);
        }
        Some(order)
    }

    fn depth(&self, side: Side, n: usize) -> Vec<(Price, u64)> {
        match side {
            Side::Bid => self.bids.iter().rev().take(n).map(|(p, l)| (*p, l.total)).collect(),
            Side::Ask => self.asks.iter().take(n).map(|(p, l)| (*p, l.total)).collect(),
        }
    }

    fn check_invariants(&self) {
        if let (Some((bid, _)), Some((ask, _))) = (self.best_bid(), self.best_ask()) {
            assert!(bid < ask, "book is crossed");
        }
        let mut resting = 0;
        for level in self.bids.values().chain(self.asks.values()) {
            assert!(!level.orders.is_empty());
            assert_eq!(level.total, level.orders.iter().map(|o| u64::from(o.qty)).sum::<u64>());
            resting += level.orders.len();
        }
        assert_eq!(resting, self.index.len());
    }
}

fn main() {
    let mut book = Book::default();
    for (id, side, price, qty) in [
        (1, Side::Bid, 10_000, 5),
        (2, Side::Bid, 10_000, 7),
        (3, Side::Bid, 9_990, 10),
        (4, Side::Ask, 10_010, 4),
        (5, Side::Ask, 10_030, 8),
        (6, Side::Ask, 10_010, 6),
    ] {
        book.add(id, side, price, qty).unwrap();
        book.check_invariants();
    }
    println!("best bid = {:?}, best ask = {:?}", book.best_bid(), book.best_ask());
    println!("bid depth = {:?}", book.depth(Side::Bid, 5));
    println!("ask depth = {:?}", book.depth(Side::Ask, 5));
    println!("spread = {:?}", book.best_ask().unwrap().0 - book.best_bid().unwrap().0);

    println!("cancel 1 -> {:?}", book.cancel(1));
    println!("best bid after cancel = {:?}", book.best_bid());
    println!("cancel 3 -> {:?}, bid levels now {}", book.cancel(3), book.bids.len());
    println!("cancel unknown -> {:?}", book.cancel(99));
    println!("front of the 10000 queue is order {}", book.bids[&10_000].orders[0].id);
    println!("duplicate: {:?}", book.add(2, Side::Bid, 9_000, 1));
    println!("zero quantity: {:?}", book.add(10, Side::Bid, 9_000, 0));
    println!("crossing bid: {:?}", book.add(11, Side::Bid, 10_010, 1));
    println!("crossing ask: {:?}", book.add(12, Side::Ask, 10_000, 1));
    book.check_invariants();
    println!("invariants hold");
}

