use std::collections::BTreeMap;

fn volume_to_buy(asks: &BTreeMap<i64, u32>, qty: u32) -> Option<i64> {
    let mut remaining = qty;
    let mut cost = 0i64;
    for (&price, &available) in asks {
        if remaining == 0 {
            break;
        }
        let take = remaining.min(available);
        cost += price * i64::from(take);
        remaining -= take;
    }
    (remaining == 0).then_some(cost)
}

fn main() {
    let asks = BTreeMap::from([(101, 4), (102, 8), (105, 20)]);
    assert_eq!(volume_to_buy(&asks, 10), Some(1016));
    assert_eq!(volume_to_buy(&asks, 4), Some(404));
    assert_eq!(volume_to_buy(&asks, 33), None);
    assert_eq!(volume_to_buy(&asks, 0), Some(0));
    println!("10 shares cost {:?}, 33 shares cost {:?}", volume_to_buy(&asks, 10), volume_to_buy(&asks, 33));
}

