use std::collections::{BTreeMap, HashMap, VecDeque};

pub type Price = i64;
pub type Qty = u32;
pub type OrderId = u64;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Side {
    Buy,
    Sell,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Limit(Price),
    Market,
}

/// Time in force: Gtc rests the unfilled remainder, Ioc cancels it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Tif {
    Gtc,
    Ioc,
}

#[derive(Clone, Copy, Debug)]
pub struct Order {
    pub id: OrderId,
    pub side: Side,
    pub kind: Kind,
    pub qty: Qty,
    pub tif: Tif,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Trade {
    pub taker: OrderId,
    pub maker: OrderId,
    pub price: Price,
    pub qty: Qty,
}

#[derive(Debug, PartialEq, Eq)]
pub enum Reject {
    /// The id belongs to an order that is still resting. Ids of filled or cancelled orders may be reused.
    DuplicateId,
    ZeroQuantity,
}

#[derive(Debug, Default, PartialEq, Eq)]
pub struct Outcome {
    pub trades: Vec<Trade>,
    /// Quantity left resting on the book (Gtc limit orders only).
    pub resting: Option<Qty>,
    /// Quantity cancelled because it could not trade and may not rest.
    pub cancelled: Qty,
}

struct Resting {
    id: OrderId,
    qty: Qty,
}

type Levels = BTreeMap<Price, VecDeque<Resting>>;

#[derive(Default)]
pub struct Engine {
    bids: Levels,
    asks: Levels,
    index: HashMap<OrderId, (Side, Price)>,
}

/// Trade the taker against the best prices of `book` until it is filled or no price is acceptable.
fn match_against(
    book: &mut Levels,
    index: &mut HashMap<OrderId, (Side, Price)>,
    taker: &Order,
    limit: Option<Price>,
    remaining: &mut Qty,
    trades: &mut Vec<Trade>,
) {
    while *remaining > 0 {
        let best = match taker.side {
            Side::Buy => book.keys().next().copied(),
            Side::Sell => book.keys().next_back().copied(),
        };
        let Some(price) = best else { break };
        let acceptable = limit.is_none_or(|l| match taker.side {
            Side::Buy => price <= l,
            Side::Sell => price >= l,
        });
        if !acceptable {
            break;
        }
        let queue = book.get_mut(&price).expect("best price has a queue");
        while *remaining > 0 {
            let Some(front) = queue.front_mut() else { break };
            let qty = (*remaining).min(front.qty);
            trades.push(Trade { taker: taker.id, maker: front.id, price, qty });
            front.qty -= qty;
            *remaining -= qty;
            if front.qty == 0 {
                index.remove(&front.id);
                queue.pop_front();
            }
        }
        if queue.is_empty() {
            book.remove(&price);
        }
    }
}

impl Engine {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn best_bid(&self) -> Option<Price> {
        self.bids.keys().next_back().copied()
    }

    pub fn best_ask(&self) -> Option<Price> {
        self.asks.keys().next().copied()
    }

    /// Total quantity resting at a price on one side.
    pub fn depth_at(&self, side: Side, price: Price) -> Qty {
        let levels = if side == Side::Buy { &self.bids } else { &self.asks };
        levels.get(&price).map_or(0, |q| q.iter().map(|o| o.qty).sum())
    }

    pub fn submit(&mut self, order: Order) -> Result<Outcome, Reject> {
        if order.qty == 0 {
            return Err(Reject::ZeroQuantity);
        }
        if self.index.contains_key(&order.id) {
            return Err(Reject::DuplicateId);
        }
        let limit = match order.kind {
            Kind::Limit(price) => Some(price),
            Kind::Market => None,
        };
        let mut remaining = order.qty;
        let mut trades = Vec::new();
        let opposite = if order.side == Side::Buy { &mut self.asks } else { &mut self.bids };
        match_against(opposite, &mut self.index, &order, limit, &mut remaining, &mut trades);

        let mut outcome = Outcome { trades, resting: None, cancelled: 0 };
        if remaining > 0 {
            match (order.kind, order.tif) {
                (Kind::Limit(price), Tif::Gtc) => {
                    let levels = if order.side == Side::Buy { &mut self.bids } else { &mut self.asks };
                    levels.entry(price).or_default().push_back(Resting { id: order.id, qty: remaining });
                    self.index.insert(order.id, (order.side, price));
                    outcome.resting = Some(remaining);
                }
                _ => outcome.cancelled = remaining,
            }
        }
        Ok(outcome)
    }

    /// Cancel a resting order; returns false if the id is not resting.
    pub fn cancel(&mut self, id: OrderId) -> bool {
        let Some((side, price)) = self.index.remove(&id) else { return false };
        let levels = if side == Side::Buy { &mut self.bids } else { &mut self.asks };
        let queue = levels.get_mut(&price).expect("indexed order has a level");
        queue.retain(|o| o.id != id);
        if queue.is_empty() {
            levels.remove(&price);
        }
        true
