use std::collections::VecDeque;

struct Lot {
    qty: i64,
    price: i64,
}

#[derive(Default)]
struct Account {
    lots: VecDeque<Lot>,
    realized: i128,
    fees: i128,
}

impl Account {
    /// `signed_qty` is positive for buys and negative for sells.
    fn fill(&mut self, signed_qty: i64, price: i64, fee: i64) {
        let mut remaining = signed_qty;
        while remaining != 0 {
            match self.lots.front_mut() {
                Some(lot) if lot.qty.signum() != remaining.signum() => {
                    let closed = remaining.abs().min(lot.qty.abs());
                    let per_unit = if lot.qty > 0 { price - lot.price } else { lot.price - price };
                    self.realized += i128::from(per_unit) * i128::from(closed);
                    lot.qty -= lot.qty.signum() * closed;
                    remaining -= remaining.signum() * closed;
                    if lot.qty == 0 {
                        self.lots.pop_front();
                    }
                }
                _ => break,
            }
        }
        if remaining != 0 {
            self.lots.push_back(Lot { qty: remaining, price });
        }
        self.fees += i128::from(fee);
    }

    fn position(&self) -> i64 {
        self.lots.iter().map(|l| l.qty).sum()
    }

    fn unrealized(&self, mark: i64) -> i128 {
        self.lots.iter().map(|l| i128::from(mark - l.price) * i128::from(l.qty)).sum()
    }

    fn net(&self, mark: i64) -> i128 {
        self.realized + self.unrealized(mark) - self.fees
    }
}

fn report(label: &str, account: &Account, mark: i64) {
    println!(
        "{label}: position {}, realized {}, unrealized {}, fees {}, net {}",
        account.position(),
        account.realized,
        account.unrealized(mark),
        account.fees,
        account.net(mark)
    );
}

fn main() {
    let mut account = Account::default();
    account.fill(10, 100, 1);
    account.fill(5, 102, 1);
    report("after two buys (mark 103)", &account, 103);

    account.fill(-12, 105, 1);
    report("after selling 12 @ 105 (mark 104)", &account, 104);
    println!("remaining lot: {} @ {}", account.lots[0].qty, account.lots[0].price);

    account.fill(-8, 103, 1);
    report("after selling 8 @ 103, flipped short (mark 100)", &account, 100);
    println!("short lot: {} @ {}", account.lots[0].qty, account.lots[0].price);

    let mut flat = Account::default();
    flat.fill(10, 100, 0);
    flat.fill(-10, 100, 0);
    println!("round trip at one price: position {}, net {}", flat.position(), flat.net(100));
}

