    println!("finite-difference vega agrees: {}", (fd_vega - c.vega()).abs() < 1e-2);

    println!("cdf(0) = {:.4}, cdf(1.96) = {:.4}, cdf(-1.96) = {:.4}", cdf(0.0), cdf(1.96), cdf(-1.96));
