use std::f64::consts::PI;

struct Rng(u64);

impl Rng {
    fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }

    /// Uniform in (0, 1]: never zero, so ln() below is always finite.
    fn uniform(&mut self) -> f64 {
        1.0 - (self.next_u64() >> 11) as f64 / (1u64 << 53) as f64
    }

    /// Box-Muller: two independent standard normals from two uniforms.
    fn normal_pair(&mut self) -> (f64, f64) {
        let (u1, u2) = (self.uniform(), self.uniform());
        let radius = (-2.0 * u1.ln()).sqrt();
        (radius * (2.0 * PI * u2).cos(), radius * (2.0 * PI * u2).sin())
    }
}

fn pdf(x: f64) -> f64 {
    (-0.5 * x * x).exp() / (2.0 * PI).sqrt()
}

fn cdf(x: f64) -> f64 {
    let t = 1.0 / (1.0 + 0.231_641_9 * x.abs());
    let poly = t * (0.319_381_530 + t * (-0.356_563_782 + t * (1.781_477_937 + t * (-1.821_255_978 + t * 1.330_274_429))));
    let upper = pdf(x) * poly;
    if x >= 0.0 { 1.0 - upper } else { upper }
}

#[derive(Clone, Copy)]
struct Contract {
    spot: f64,
    strike: f64,
    rate: f64,
    vol: f64,
    years: f64,
}

impl Contract {
    fn black_scholes_call(&self) -> f64 {
        let sd = self.vol * self.years.sqrt();
        let d1 = ((self.spot / self.strike).ln() + (self.rate + 0.5 * self.vol * self.vol) * self.years) / sd;
        self.spot * cdf(d1) - self.strike * (-self.rate * self.years).exp() * cdf(d1 - sd)
    }

    fn terminal(&self, z: f64) -> f64 {
        self.spot * ((self.rate - 0.5 * self.vol * self.vol) * self.years + self.vol * self.years.sqrt() * z).exp()
    }

    fn discounted_call_payoff(&self, z: f64) -> f64 {
        (self.terminal(z) - self.strike).max(0.0) * (-self.rate * self.years).exp()
    }
}

/// Mean and standard error of a set of independent observations.
fn mean_and_se(values: &[f64]) -> (f64, f64) {
    let n = values.len() as f64;
    let mean = values.iter().sum::<f64>() / n;
    let variance = values.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / (n - 1.0);
    (mean, (variance / n).sqrt())
}

fn main() {
    let c = Contract { spot: 100.0, strike: 100.0, rate: 0.05, vol: 0.2, years: 1.0 };
    let exact = c.black_scholes_call();
    println!("Black-Scholes call = {exact:.4}");

    let mut rng = Rng(0x0DDB_1A5E_5BAD_5EED);
    let mut plain = Vec::with_capacity(200_000);
    for _ in 0..100_000 {
        let (z1, z2) = rng.normal_pair();
        plain.push(c.discounted_call_payoff(z1));
        plain.push(c.discounted_call_payoff(z2));
    }
    let (plain_mean, plain_se) = mean_and_se(&plain);

    let mut rng = Rng(0x0DDB_1A5E_5BAD_5EED);
    let mut paired = Vec::with_capacity(100_000);
    for _ in 0..50_000 {
        let (z1, z2) = rng.normal_pair();
        for z in [z1, z2] {
            paired.push(0.5 * (c.discounted_call_payoff(z) + c.discounted_call_payoff(-z)));
        }
    }
    let (anti_mean, anti_se) = mean_and_se(&paired);
    println!("plain:      {plain_mean:.3} +/- {plain_se:.3} ({} payoffs)", plain.len());
    println!("antithetic: {anti_mean:.3} +/- {anti_se:.3} ({} payoffs)", paired.len() * 2);
    println!("plain within 4 se of exact: {}", (plain_mean - exact).abs() < 4.0 * plain_se);
    println!("antithetic within 4 se of exact: {}", (anti_mean - exact).abs() < 4.0 * anti_se);
    println!("antithetic standard error is smaller: {}", anti_se < plain_se);

    let mut rng = Rng(7);
    let finite = (0..100_000).all(|_| {
        let (a, b) = rng.normal_pair();
        a.is_finite() && b.is_finite()
    });
    println!("all Box-Muller outputs finite: {finite}");
}

