fn var_nearest_rank(pnls: &[i64], confidence_bp: u32) -> i64 {
    assert!(!pnls.is_empty() && (1..10_000).contains(&confidence_bp));
    let n = pnls.len() as u64;
    let k = (n * u64::from(10_000 - confidence_bp)).div_ceil(10_000).max(1) as usize;
    -sorted(pnls)[k - 1]
}

/// Expected shortfall: the average loss over the k worst outcomes, rounded half away from zero.
fn expected_shortfall(pnls: &[i64], confidence_bp: u32) -> i64 {
    let n = pnls.len() as u64;
    let k = (n * u64::from(10_000 - confidence_bp)).div_ceil(10_000).max(1) as usize;
    let tail: i128 = sorted(pnls)[..k].iter().map(|&x| -i128::from(x)).sum();
    let k = k as i128;
    ((2 * tail + k) / (2 * k)) as i64
}

fn sample_pnls() -> Vec<i64> {
    let mut pnls: Vec<i64> = (0..250).map(|i| (i * 7919) % 201 - 100).collect();
    pnls[17] = -400;
    pnls[123] = -250;
    pnls
}

fn var_linear(pnls: &[i64], confidence_bp: u32) -> f64 {
    let sorted = sorted(pnls);
    let position = (sorted.len() - 1) as f64 * f64::from(10_000 - confidence_bp) / 10_000.0;
    let (lo, hi) = (position.floor() as usize, position.ceil() as usize);
    let fraction = position - lo as f64;
    -(sorted[lo] as f64 * (1.0 - fraction) + sorted[hi] as f64 * fraction)
}

fn main() {
    let pnls = sample_pnls();
    let ordered = sorted(&pnls);
    for confidence in [9000, 9500, 9900] {
        let value = var_linear(&pnls, confidence);
        let position = (ordered.len() - 1) as f64 * f64::from(10_000 - confidence) / 10_000.0;
        let (low, high) = (-(ordered[position.ceil() as usize] as f64), -(ordered[position.floor() as usize] as f64));
        assert!(value >= low - 1e-9 && value <= high + 1e-9);
        println!("{}%: linear VaR = {value:.2}, nearest rank = {}", confidence / 100, var_nearest_rank(&pnls, confidence));
    }
    assert!(var_linear(&pnls, 9500) <= var_linear(&pnls, 9900));
    println!("expected shortfall at 95% = {}", expected_shortfall(&pnls, 9500));
}

