    let data = bars(&[100, 104, 108, 112]);
    let report = run(&data, &mut BuyAndHold, Costs::default());
    assert_eq!(*report.equity.last().unwrap(), i128::from(112 - 100));
    assert_eq!(report.position, 1);
}

