    let data = bars(&[100, 104, 108, 112]);
    let free = run(&data, &mut BuyAndHold, Costs::default());
    let costly = run(&data, &mut BuyAndHold, Costs { slippage_ticks: 2, fee_per_fill: 3 });
    assert_eq!(free.equity.last().unwrap() - costly.equity.last().unwrap(), 2 + 3);
}

