fn flat_strategy_never_trades() {
    let report = run(&bars(&[100, 101, 99, 105]), &mut Flat, Costs { slippage_ticks: 5, fee_per_fill: 5 });
    assert!(report.fills.is_empty());
    assert!(report.equity.iter().all(|&e| e == 0));
}

