fn a_signal_on_the_last_bar_cannot_fill() {
    let data = bars(&[100, 101, 102, 103]);
    let report = run(&data, &mut LateSignal { last_ts: 3 }, Costs::default());
    assert!(report.fills.is_empty());
}

