fn sma_cross_goes_long_on_a_trend_and_is_deterministic() {
    let closes: Vec<i64> = (0..40).map(|i| 1000 + i * 3).collect();
    let data = bars(&closes);
    let first = run(&data, &mut SmaCross::new(3, 8), Costs::default());
    let second = run(&data, &mut SmaCross::new(3, 8), Costs::default());
    assert_eq!(first.fills, second.fills);
    assert_eq!(first.equity, second.equity);
    assert_eq!(first.position, 1);
    assert!(*first.equity.last().unwrap() > 0);
}

