use std::collections::BTreeMap;
use std::sync::mpsc::{Receiver, SyncSender};
use std::thread::{self, JoinHandle};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Side {
    Bid,
    Ask,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Update {
    Add { seq: u64, side: Side, price: i64, qty: u64 },
    Reduce { seq: u64, side: Side, price: i64, qty: u64 },
    /// Last message of a session: the consumer stops cleanly after it.
    Shutdown { seq: u64 },
}

impl Update {
    pub fn seq(&self) -> u64 {
        match *self {
            Update::Add { seq, .. } | Update::Reduce { seq, .. } | Update::Shutdown { seq } => seq,
        }
    }
}

#[derive(Default)]
pub struct Book {
    bids: BTreeMap<i64, u64>,
    asks: BTreeMap<i64, u64>,
    pub bad_reduces: usize,
}

impl Book {
    fn levels(&mut self, side: Side) -> &mut BTreeMap<i64, u64> {
        if side == Side::Bid { &mut self.bids } else { &mut self.asks }
    }

    pub fn apply(&mut self, update: &Update) {
        match *update {
            Update::Add { side, price, qty, .. } => *self.levels(side).entry(price).or_insert(0) += qty,
            Update::Reduce { side, price, qty, .. } => {
                let levels = self.levels(side);
                match levels.get_mut(&price) {
                    Some(level) if *level >= qty => {
                        *level -= qty;
                        if *level == 0 {
                            levels.remove(&price);
                        }
                    }
                    _ => self.bad_reduces += 1,
                }
            }
            Update::Shutdown { .. } => {}
        }
    }

    pub fn best_bid(&self) -> Option<(i64, u64)> {
        self.bids.last_key_value().map(|(p, q)| (*p, *q))
    }

    pub fn best_ask(&self) -> Option<(i64, u64)> {
        self.asks.first_key_value().map(|(p, q)| (*p, *q))
    }
}

#[derive(Debug, PartialEq, Eq)]
pub struct Summary {
    pub applied: usize,
    /// (expected sequence number, received sequence number) for every discontinuity.
    pub gaps: Vec<(u64, u64)>,
    pub best_bid: Option<(i64, u64)>,
    pub best_ask: Option<(i64, u64)>,
    /// True only if a Shutdown message arrived; false if the sender vanished or `limit` was hit.
    pub clean_shutdown: bool,
    /// Updates whose sequence number was already seen; they are ignored, not applied.
    pub duplicates: usize,
    /// Reduce messages that matched no resting quantity; they are counted, never applied.
    pub bad_reduces: usize,
}

/// Send every update, stopping quietly if the receiver is gone. Returns how many were sent.
pub fn spawn_producer(updates: Vec<Update>, tx: SyncSender<Update>) -> JoinHandle<usize> {
    thread::spawn(move || {
        let mut sent = 0;
        for update in updates {
            if tx.send(update).is_err() {
                break; // consumer hung up: stop instead of panicking
            }
            sent += 1;
        }
        sent
    })
}

/// Apply updates from `rx` until Shutdown, disconnection, or `limit` applied updates.
pub fn consume(rx: Receiver<Update>, limit: Option<usize>) -> Summary {
    let mut book = Book::default();
    let mut next_seq = None;
    let mut gaps = Vec::new();
    let mut applied = 0;
    let mut duplicates = 0;
    let mut clean_shutdown = false;
    while limit.is_none_or(|l| applied < l) {
        let Ok(update) = rx.recv() else { break };
        let seq = update.seq();
        if let Some(expected) = next_seq {
            if seq < expected {
                duplicates += 1;
                continue;
            }
            if seq > expected {
                gaps.push((expected, seq));
            }
        }
        next_seq = Some(seq + 1);
        if matches!(update, Update::Shutdown { .. }) {
            clean_shutdown = true;
            break;
        }
        book.apply(&update);
        applied += 1;
    }
    Summary { applied, gaps, best_bid: book.best_bid(), best_ask: book.best_ask(), clean_shutdown, duplicates, bad_reduces: book.bad_reduces }
}

