//! Parser -> book -> strategy -> risk -> gateway, joined by bounded preallocated rings.

use std::collections::VecDeque;

pub const INBOUND_FRAME: usize = 10; // 'U' side:u8 price:u32 qty:u32 (big-endian)
pub const OUTBOUND_FRAME: usize = 18; // 'O' side:u8 price:u32 qty:u32 id:u64 (big-endian)
const PRICES: usize = 1024;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Side {
    Bid,
    Ask,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Update {
    pub side: Side,
    pub price: u32,
    pub qty: u32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Intent {
    pub side: Side,
    pub price: u32,
    pub qty: u32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Order {
    pub id: u64,
    pub side: Side,
    pub price: u32,
    pub qty: u32,
}

#[derive(Debug, PartialEq, Eq)]
pub enum PipelineError {
    BadType(u8),
    BadSide(u8),
    PriceOutOfRange(u32),
}

/// Fixed-capacity FIFO; capacity is reserved once and the ring never grows.
pub struct Ring<T> {
    items: VecDeque<T>,
    capacity: usize,
}

impl<T> Ring<T> {
    pub fn with_capacity(capacity: usize) -> Self {
        Ring { items: VecDeque::with_capacity(capacity), capacity }
    }

    pub fn push(&mut self, item: T) -> Result<(), T> {
        if self.items.len() == self.capacity {
            return Err(item);
        }
        self.items.push_back(item);
        Ok(())
    }

    pub fn pop(&mut self) -> Option<T> {
        self.items.pop_front()
    }

    pub fn free(&self) -> usize {
        self.capacity - self.items.len()
    }

    /// Slots actually reserved by the allocator; must not change while running.
    pub fn reserved(&self) -> usize {
        self.items.capacity()
    }
}

/// Dense quantity-by-price book with absolute level updates (quantity 0 removes the level).
struct Book {
    bids: Vec<u32>,
    asks: Vec<u32>,
}

impl Book {
    fn set(&mut self, side: Side, price: u32, qty: u32) -> Result<(), PipelineError> {
        let slot = self.slot(side, price)?;
        *slot = qty;
        Ok(())
    }

    fn slot(&mut self, side: Side, price: u32) -> Result<&mut u32, PipelineError> {
        let levels = if side == Side::Bid { &mut self.bids } else { &mut self.asks };
        levels.get_mut(price as usize).ok_or(PipelineError::PriceOutOfRange(price))
    }

    fn best_bid(&self) -> Option<u32> {
        self.bids.iter().rposition(|&q| q > 0).map(|p| p as u32)
    }

    fn best_ask(&self) -> Option<u32> {
        self.asks.iter().position(|&q| q > 0).map(|p| p as u32)
    }
}

/// Quote one tick inside a wide market: improve the bid and the ask when the spread is 3+ ticks.
fn decide(bid: Option<u32>, ask: Option<u32>) -> [Option<Intent>; 2] {
    match (bid, ask) {
        (Some(bid), Some(ask)) if ask >= bid + 3 => [
            Some(Intent { side: Side::Bid, price: bid + 1, qty: 10 }),
            Some(Intent { side: Side::Ask, price: ask - 1, qty: 10 }),
        ],
        _ => [None, None],
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Reason {
    ZeroPrice = 0,
    QtyTooLarge = 1,
    ExposureLimit = 2,
}

struct Risk {
    max_qty: u32,
    max_exposure: u32,
    exposure: u32,
}

impl Risk {
    fn check(&mut self, intent: &Intent) -> Result<(), Reason> {
        if intent.price == 0 {
            return Err(Reason::ZeroPrice);
        }
        if intent.qty > self.max_qty {
            return Err(Reason::QtyTooLarge);
        }
        if self.exposure + intent.qty > self.max_exposure {
            return Err(Reason::ExposureLimit);
        }
        self.exposure += intent.qty;
        Ok(())
    }
}

pub struct Pipeline {
    updates: Ring<Update>,
    intents: Ring<Intent>,
    orders: Ring<Order>,
    book: Book,
    risk: Risk,
    outbound: Vec<u8>,
    next_id: u64,
    pub applied: usize,
    pub intents_generated: usize,
    pub approved: usize,
    pub rejected: [usize; 3],
}

impl Pipeline {
    pub fn new(ring_capacity: usize) -> Self {
        assert!(ring_capacity >= 2, "the intent ring must hold the two quotes one update can produce");
        Pipeline {
            updates: Ring::with_capacity(ring_capacity),
            intents: Ring::with_capacity(ring_capacity),
            orders: Ring::with_capacity(ring_capacity),
            book: Book { bids: vec![0; PRICES], asks: vec![0; PRICES] },
            risk: Risk { max_qty: 10, max_exposure: 25, exposure: 0 },
            outbound: Vec::with_capacity(1 << 16),
            next_id: 1,
            applied: 0,
            intents_generated: 0,
            approved: 0,
            rejected: [0; 3],
        }
    }

    /// Reserved slots of the three rings, for checking that nothing grows at run time.
    pub fn reserved(&self) -> [usize; 3] {
        [self.updates.reserved(), self.intents.reserved(), self.orders.reserved()]
    }

    pub fn outbound(&self) -> &[u8] {
        &self.outbound
    }

    pub fn best_prices(&self) -> (Option<u32>, Option<u32>) {
        (self.book.best_bid(), self.book.best_ask())
    }

    pub fn exposure(&self) -> u32 {
        self.risk.exposure
    }

    /// Consume whole inbound frames from `bytes`; returns bytes consumed so the caller keeps any partial tail.
    pub fn process(&mut self, bytes: &[u8]) -> Result<usize, PipelineError> {
        let mut offset = 0;
        while let Some(frame) = bytes.get(offset..offset + INBOUND_FRAME) {
            if frame[0] != b'U' {
                return Err(PipelineError::BadType(frame[0]));
            }
            let side = match frame[1] {
                b'B' => Side::Bid,
                b'S' => Side::Ask,
                other => return Err(PipelineError::BadSide(other)),
            };
            let update = Update {
                side,
                price: u32::from_be_bytes(frame[2..6].try_into().unwrap()),
                qty: u32::from_be_bytes(frame[6..10].try_into().unwrap()),
            };
            if self.updates.free() == 0 {
                self.pump()?;
            }
            self.updates.push(update).expect("pump made room");
            offset += INBOUND_FRAME;
        }
        self.pump()?;
        Ok(offset)
    }

    /// Run the stages back to front until nothing can move; a stage only runs if its output has room.
    fn pump(&mut self) -> Result<(), PipelineError> {
        loop {
            let mut progressed = false;
            if let Some(order) = self.orders.pop() {
                self.outbound.push(b'O');
                self.outbound.push(if order.side == Side::Bid { b'B' } else { b'S' });
                self.outbound.extend_from_slice(&order.price.to_be_bytes());
                self.outbound.extend_from_slice(&order.qty.to_be_bytes());
                self.outbound.extend_from_slice(&order.id.to_be_bytes());
                progressed = true;
            }
            if self.orders.free() >= 1 {
                if let Some(intent) = self.intents.pop() {
                    match self.risk.check(&intent) {
                        Ok(()) => {
                            let order = Order { id: self.next_id, side: intent.side, price: intent.price, qty: intent.qty };
                            self.next_id += 1;
                            self.orders.push(order).expect("space checked");
                            self.approved += 1;
                        }
                        Err(reason) => self.rejected[reason as usize] += 1,
                    }
                    progressed = true;
                }
            }
            if self.intents.free() >= 2 {
                if let Some(update) = self.updates.pop() {
                    self.book.set(update.side, update.price, update.qty)?;
                    for intent in decide(self.book.best_bid(), self.book.best_ask()).into_iter().flatten() {
                        self.intents.push(intent).expect("space checked");
                        self.intents_generated += 1;
                    }
                    self.applied += 1;
                    progressed = true;
                }
            }
            if !progressed {
                return Ok(());
            }
        }
    }
}

use pipeline_lab::{OUTBOUND_FRAME, Pipeline};

fn main() {
    let mut stream = Vec::new();
    for i in 0..200u32 {
        let bid = i % 2 == 0;
        let price = if bid { 480 + (i * 7) % 25 } else { 505 + (i * 11) % 25 };
        let qty = if i % 5 == 4 { 0 } else { 1 + i % 9 };
        stream.extend([b'U', if bid { b'B' } else { b'S' }]);
        stream.extend(price.to_be_bytes());
        stream.extend(qty.to_be_bytes());
    }

    let mut pipeline = Pipeline::new(8);
    let reserved_before = pipeline.reserved();
    let consumed = pipeline.process(&stream).unwrap();
    println!("consumed {consumed} of {} bytes", stream.len());
    println!("updates applied = {}, intents = {}", pipeline.applied, pipeline.intents_generated);
    println!("approved = {}, rejected [zero price, qty, exposure] = {:?}", pipeline.approved, pipeline.rejected);
    println!("orders sent = {} ({} bytes)", pipeline.outbound().len() / OUTBOUND_FRAME, pipeline.outbound().len());
    println!("best bid/ask = {:?}", pipeline.best_prices());
    println!("rings grew: {}", pipeline.reserved() != reserved_before);
}

use pipeline_lab::{INBOUND_FRAME, OUTBOUND_FRAME, Pipeline, PipelineError};

fn frame(side: u8, price: u32, qty: u32) -> Vec<u8> {
    let mut f = vec![b'U', side];
    f.extend(price.to_be_bytes());
    f.extend(qty.to_be_bytes());
    f
}

/// A recorded session: deterministic updates around a 480..=530 price band, a few removals.
fn recorded_stream(n: u32) -> Vec<u8> {
    let mut bytes = Vec::new();
    for i in 0..n {
        let bid = i % 2 == 0;
        let price = if bid { 480 + (i * 7) % 25 } else { 505 + (i * 11) % 25 };
        let qty = if i % 5 == 4 { 0 } else { 1 + i % 9 };
        bytes.extend(frame(if bid { b'B' } else { b'S' }, price, qty));
    }
    bytes
}

fn run(capacity: usize, stream: &[u8]) -> Pipeline {
    let mut pipeline = Pipeline::new(capacity);
    assert_eq!(pipeline.process(stream).unwrap(), stream.len());
    pipeline
}

#[test]
fn recorded_session_reaches_the_pinned_final_state() {
    let stream = recorded_stream(200);
    let pipeline = run(8, &stream);
    // Golden values pinned from a reviewed run: two 10-lot orders use 20 of the 25 exposure limit,
    // so every later intent is rejected for exposure (2 + 60 = 62 intents).
    assert_eq!(pipeline.applied, 200);
    assert_eq!(pipeline.intents_generated, 62);
    assert_eq!(pipeline.approved, 2);
    assert_eq!(pipeline.rejected, [0, 0, 60]);
    assert_eq!(pipeline.best_prices(), (Some(504), Some(505)));
    assert_eq!(pipeline.outbound().len(), 2 * OUTBOUND_FRAME);
}

#[test]
fn every_intent_is_either_approved_or_rejected_exactly_once() {
    let pipeline = run(8, &recorded_stream(200));
    let rejected: usize = pipeline.rejected.iter().sum();
    assert_eq!(pipeline.approved + rejected, pipeline.intents_generated);
    assert_eq!(pipeline.outbound().len(), pipeline.approved * OUTBOUND_FRAME);
}

#[test]
fn results_do_not_depend_on_ring_size() {
    let stream = recorded_stream(500);
    let reference = run(1024, &stream);
    for capacity in [2, 3, 5, 64] {
        let small = run(capacity, &stream);
        assert_eq!(small.applied, reference.applied, "capacity {capacity}");
        assert_eq!(small.intents_generated, reference.intents_generated, "capacity {capacity}");
        assert_eq!(small.approved, reference.approved, "capacity {capacity}");
        assert_eq!(small.rejected, reference.rejected, "capacity {capacity}");
        assert_eq!(small.outbound(), reference.outbound(), "capacity {capacity}");
        assert_eq!(small.best_prices(), reference.best_prices(), "capacity {capacity}");
    }
}

#[test]
fn rings_do_not_grow_while_running() {
    let mut pipeline = Pipeline::new(8);
    let before = pipeline.reserved();
    pipeline.process(&recorded_stream(2000)).unwrap();
    assert_eq!(pipeline.reserved(), before);
}

#[test]
fn exposure_never_exceeds_the_limit() {
    let pipeline = run(8, &recorded_stream(2000));
    assert!(pipeline.exposure() <= 25);
    assert!(pipeline.rejected[2] > 0, "the limit should actually bind in this session");
}

#[test]
fn a_partial_trailing_frame_is_left_for_the_next_read() {
    let stream = recorded_stream(5);
    let mut pipeline = Pipeline::new(4);
    let cut = 3 * INBOUND_FRAME + 4;
    let consumed = pipeline.process(&stream[..cut]).unwrap();
    assert_eq!(consumed, 3 * INBOUND_FRAME);
    assert_eq!(pipeline.applied, 3);
    let consumed_rest = pipeline.process(&stream[consumed..]).unwrap();
    assert_eq!(consumed + consumed_rest, stream.len());
    assert_eq!(pipeline.applied, 5);
}

#[test]
fn malformed_input_is_reported_not_applied() {
    let mut pipeline = Pipeline::new(4);
    assert_eq!(pipeline.process(&[b'Z'; INBOUND_FRAME]), Err(PipelineError::BadType(b'Z')));
    assert_eq!(pipeline.process(&frame(b'?', 10, 1)), Err(PipelineError::BadSide(b'?')));
    assert_eq!(pipeline.process(&frame(b'B', 5000, 1)), Err(PipelineError::PriceOutOfRange(5000)));
    assert_eq!(pipeline.applied, 0);
}

