        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }

    fn range(&mut self, low: i64, high: i64) -> i64 {
        low + (self.next() % (high - low + 1) as u64) as i64
    }
}

fn two_trades(prices: &[i64]) -> i64 {
    let (mut buy1, mut sell1, mut buy2, mut sell2) = (i64::MIN / 2, 0, i64::MIN / 2, 0);
    for &p in prices {
        buy1 = buy1.max(-p);
        sell1 = sell1.max(buy1 + p);
        buy2 = buy2.max(sell1 - p);
        sell2 = sell2.max(buy2 + p);
    }
    sell2
}

fn two_trades_brute(prices: &[i64]) -> i64 {
    let n = prices.len();
    let mut best = 0;
    // One trade is the case where the second trade is empty, so try single trades too.
    for a in 0..n {
        for b in a + 1..n {
            best = best.max(prices[b] - prices[a]);
            for c in b + 1..n {
                for d in c + 1..n {
                    best = best.max(prices[b] - prices[a] + prices[d] - prices[c]);
                }
            }
        }
    }
    best
}

fn main() {
    assert_eq!(two_trades(&[3, 3, 5, 0, 0, 3, 1, 4]), 6);
    assert_eq!(two_trades(&[1, 2, 3, 4, 5]), 4);
    assert_eq!(two_trades(&[7, 6, 4, 3, 1]), 0);
    let mut rng = Rng(42);
    for _ in 0..500 {
        let n = rng.range(0, 12) as usize;
        let prices: Vec<i64> = (0..n).map(|_| rng.range(0, 20)).collect();
        assert_eq!(two_trades(&prices), two_trades_brute(&prices), "{prices:?}");
    }
    println!("two trades on [3, 3, 5, 0, 0, 3, 1, 4] = {}", two_trades(&[3, 3, 5, 0, 0, 3, 1, 4]));
}

