struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }

    fn range(&mut self, low: i64, high: i64) -> i64 {
        low + (self.next() % (high - low + 1) as u64) as i64
    }
}

fn kadane<F: Fn(i64) -> i64>(values: &[i64], f: F) -> i64 {
    let (mut best, mut current) = (f(values[0]), f(values[0]));
    for &v in &values[1..] {
        current = f(v).max(current + f(v));
        best = best.max(current);
    }
    best
}

fn circular_max(values: &[i64]) -> Option<i64> {
    if values.is_empty() {
        return None;
    }
    let total: i64 = values.iter().sum();
    let linear_max = kadane(values, |x| x);
    let min_stretch = -kadane(values, |x| -x);
    if linear_max < 0 {
        return Some(linear_max); // all negative: wrapping around would mean taking the empty stretch
    }
    Some(linear_max.max(total - min_stretch))
}

fn circular_brute(values: &[i64]) -> Option<i64> {
    let n = values.len();
    let mut best: Option<i64> = None;
    for start in 0..n {
        let mut sum = 0;
        for len in 1..=n {
            sum += values[(start + len - 1) % n];
            best = Some(best.map_or(sum, |b| b.max(sum)));
        }
    }
    best
}

fn main() {
    assert_eq!(circular_max(&[5, -3, 5]), Some(10));
    assert_eq!(circular_max(&[-3, -2, -3]), Some(-2));
    assert_eq!(circular_max(&[]), None);
    let mut rng = Rng(7);
    for _ in 0..1000 {
        let n = rng.range(0, 10) as usize;
        let values: Vec<i64> = (0..n).map(|_| rng.range(-8, 8)).collect();
        assert_eq!(circular_max(&values), circular_brute(&values), "{values:?}");
    }
    println!("circular best of [5, -3, 5] = {:?}", circular_max(&[5, -3, 5]));
}

