            let real_order: Vec<u32> = real.keys_most_recent_first().into_iter().copied().collect();
            let model_order: Vec<u32> = model.entries.iter().map(|e| e.0).collect();
            assert_eq!(real_order, model_order);
        }
    }
    println!("matches the O(n) model for capacities 1, 4 and 7 over 5000 random steps: true");
