use std::collections::VecDeque;

/// `dominated(old, new)` is true when `old` can never again be the extreme once `new` has arrived.
fn window_extreme(values: &[i64], k: usize, dominated: impl Fn(i64, i64) -> bool) -> Vec<i64> {
    assert!(k >= 1, "window size must be at least 1");
    let mut deque: VecDeque<usize> = VecDeque::new();
    let mut out = Vec::with_capacity(values.len().saturating_sub(k - 1));
    for (i, &value) in values.iter().enumerate() {
        while deque.back().is_some_and(|&b| dominated(values[b], value)) {
            deque.pop_back();
        }
        deque.push_back(i);
        if deque.front().is_some_and(|&f| f + k <= i) {
            deque.pop_front();
        }
        if i + 1 >= k {
            out.push(values[*deque.front().unwrap()]);
        }
    }
    out
}

fn window_max(values: &[i64], k: usize) -> Vec<i64> {
    window_extreme(values, k, |old, new| old <= new)
}

fn window_min(values: &[i64], k: usize) -> Vec<i64> {
    window_extreme(values, k, |old, new| old >= new)
}

fn main() {
    let prices = [1, 3, -1, -3, 5, 3, 6, 7];
    println!("rolling max (k=3): {:?}", window_max(&prices, 3));
    println!("rolling min (k=3): {:?}", window_min(&prices, 3));
    let highs = window_max(&prices, 3);
    let lows = window_min(&prices, 3);
    println!("window range: {:?}", highs.iter().zip(&lows).map(|(h, l)| h - l).collect::<Vec<_>>());
    println!("k = 1 is the identity: {}", window_max(&prices, 1) == prices);
    println!("k = n gives one window: {:?}", window_max(&prices, prices.len()));
    println!("k > n gives none: {:?}", window_max(&prices, 20));
    println!("ties: {:?}", window_max(&[2, 2, 2, 1], 2));

    let mut rng = Rng(0xD1CE);
    for _ in 0..3000 {
        let n = rng.range(0, 40) as usize;
        let k = rng.range(1, 12) as usize;
        let values: Vec<i64> = (0..n).map(|_| rng.range(-5, 5)).collect();
        let brute_max: Vec<i64> = values.windows(k).map(|w| *w.iter().max().unwrap()).collect();
        let brute_min: Vec<i64> = values.windows(k).map(|w| *w.iter().min().unwrap()).collect();
        assert_eq!(window_max(&values, k), brute_max);
        assert_eq!(window_min(&values, k), brute_min);
    }
    println!("matches the O(n*k) brute force on 3000 random inputs: true");
}

