use std::cmp::Reverse;
use std::collections::{BTreeMap, BinaryHeap};

fn top_k_per_group(items: &[(&str, i64)], k: usize) -> BTreeMap<String, Vec<i64>> {
    let mut heaps: BTreeMap<String, BinaryHeap<Reverse<i64>>> = BTreeMap::new();
    for &(group, score) in items {
        let heap = heaps.entry(group.to_string()).or_default();
        if heap.len() < k {
            heap.push(Reverse(score));
        } else if heap.peek().is_some_and(|Reverse(worst)| score > *worst) {
            heap.pop();
            heap.push(Reverse(score));
        }
    }
    heaps
        .into_iter()
        .map(|(group, heap)| {
            let mut scores: Vec<i64> = heap.into_iter().map(|Reverse(s)| s).collect();
            scores.sort_unstable_by(|a, b| b.cmp(a));
            (group, scores)
        })
        .filter(|(_, scores)| !scores.is_empty())
        .collect()
}

fn main() {
    let items = [("AAPL", 3), ("MSFT", 9), ("AAPL", 7), ("AAPL", 1), ("MSFT", 2), ("AAPL", 7), ("GOOG", 4)];
    let top = top_k_per_group(&items, 2);
    println!("{top:?}");
    let mut rng = Rng(11);
    let names = ["A", "B", "C", "D"];
    for _ in 0..500 {
