use std::collections::BTreeMap;

struct Dsu {
    parent: Vec<usize>,
    size: Vec<usize>,
    components: usize,
}

impl Dsu {
    fn new(n: usize) -> Self {
        Dsu { parent: (0..n).collect(), size: vec![1; n], components: n }
    }

    /// Iterative find with path compression: no recursion, so no stack overflow on deep chains.
    fn find(&mut self, x: usize) -> usize {
        let mut root = x;
        while self.parent[root] != root {
            root = self.parent[root];
        }
        let mut current = x;
        while self.parent[current] != root {
            let next = self.parent[current];
            self.parent[current] = root;
            current = next;
        }
        root
    }

    /// Returns true if two different clusters were merged.
    fn union(&mut self, a: usize, b: usize) -> bool {
        let (mut ra, mut rb) = (self.find(a), self.find(b));
        if ra == rb {
            return false;
        }
        if self.size[ra] < self.size[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }
        self.parent[rb] = ra;
        self.size[ra] += self.size[rb];
        self.components -= 1;
        true
    }

    fn cluster_size(&mut self, x: usize) -> usize {
        let root = self.find(x);
        self.size[root]
    }

    /// Clusters as sorted member lists, ordered by their first member.
    fn clusters(&mut self) -> Vec<Vec<usize>> {
        let mut by_root: BTreeMap<usize, Vec<usize>> = BTreeMap::new();
        for x in 0..self.parent.len() {
            let root = self.find(x);
            by_root.entry(root).or_default().push(x);
        }
        let mut clusters: Vec<Vec<usize>> = by_root.into_values().collect();
        clusters.sort();
        clusters
    }
}

fn clusters_by_bfs(n: usize, edges: &[(usize, usize)]) -> Vec<Vec<usize>> {
    let mut adjacent = vec![Vec::new(); n];
    for &(a, b) in edges {
        adjacent[a].push(b);
        adjacent[b].push(a);
    }
    let mut seen = vec![false; n];
    let mut clusters = Vec::new();
    for start in 0..n {
        if seen[start] {
            continue;
        }
        let mut component = Vec::new();
        let mut stack = vec![start];
        seen[start] = true;
        while let Some(node) = stack.pop() {
            component.push(node);
            for &next in &adjacent[node] {
                if !seen[next] {
                    seen[next] = true;
                    stack.push(next);
                }
            }
        }
        component.sort();
        clusters.push(component);
    }
    clusters.sort();
    clusters
}

fn main() {
    let names = ["AAPL", "MSFT", "GOOG", "XOM", "CVX", "JPM", "BAC"];
    let correlated = [(0, 1), (1, 2), (3, 4), (5, 6), (2, 0)];
    let mut dsu = Dsu::new(names.len());
    for &(a, b) in &correlated {
        let merged = dsu.union(a, b);
        println!("union({}, {}) merged: {merged}", names[a], names[b]);
    }
    for cluster in dsu.clusters() {
        println!("cluster: {:?}", cluster.iter().map(|&i| names[i]).collect::<Vec<_>>());
    }
    let aapl_cluster = dsu.cluster_size(0);
    println!("components = {}, AAPL cluster size = {aapl_cluster}", dsu.components);
    println!("AAPL and GOOG connected: {}", dsu.find(0) == dsu.find(2));
    println!("AAPL and XOM connected: {}", dsu.find(0) == dsu.find(3));

    let mut chain = Dsu::new(200_000);
    for i in 1..200_000 {
        chain.union(i - 1, i);
    }
    println!("a 200000-node chain is one component without stack overflow: {}", chain.components == 1);

    let mut rng = Rng(0xABCD);
    for _ in 0..1500 {
        let n = rng.range(1, 15) as usize;
        let edges: Vec<(usize, usize)> = (0..rng.range(0, 20)).map(|_| (rng.range(0, n as i64 - 1) as usize, rng.range(0, n as i64 - 1) as usize)).collect();
        let mut dsu = Dsu::new(n);
        for &(a, b) in &edges {
            dsu.union(a, b);
        }
        let expected = clusters_by_bfs(n, &edges);
        assert_eq!(dsu.clusters(), expected);
        assert_eq!(dsu.components, expected.len());
    }
    println!("matches breadth-first search on 1500 random graphs: true");
}

