fn kruskal(n: usize, mut edges: Vec<(i64, usize, usize)>) -> i64 {
    edges.sort_unstable();
    let mut dsu = Dsu::new(n);
    edges.into_iter().filter(|&(_, a, b)| dsu.union(a, b)).map(|(w, _, _)| w).sum()
}

fn prim(n: usize, weight: &[Vec<i64>]) -> i64 {
    let mut in_tree = vec![false; n];
    let mut best = vec![i64::MAX; n];
    best[0] = 0;
    let mut total = 0;
    for _ in 0..n {
        let next = (0..n).filter(|&v| !in_tree[v]).min_by_key(|&v| best[v]).unwrap();
        in_tree[next] = true;
        total += best[next];
        for v in 0..n {
            if !in_tree[v] && weight[next][v] < best[v] {
                best[v] = weight[next][v];
            }
        }
    }
    total
}

fn main() {
    let mut rng = Rng(2026);
    for _ in 0..500 {
        let n = rng.range(1, 8) as usize;
        let mut weight = vec![vec![0i64; n]; n];
        let mut edges = Vec::new();
        for a in 0..n {
            for b in a + 1..n {
                let w = rng.range(1, 20);
                weight[a][b] = w;
                weight[b][a] = w;
                edges.push((w, a, b));
            }
        }
        assert_eq!(kruskal(n, edges), prim(n, &weight));
    }
    let edges = vec![(1, 0, 1), (2, 1, 2), (3, 0, 2), (4, 2, 3)];
    println!("MST weight of a 4-node example = {}", kruskal(4, edges));
}

