use std::collections::BTreeMap;

#[derive(Default)]
struct Node {
    children: BTreeMap<u8, usize>,
    terminal: bool,
    /// Number of stored words that pass through this node (words with this prefix).
    words: usize,
}

#[derive(Debug, PartialEq)]
enum TrieError {
    NonAscii,
}

/// Arena trie: nodes live in one Vec and refer to each other by index.
struct Trie {
    nodes: Vec<Node>,
}

impl Trie {
    fn new() -> Self {
        Trie { nodes: vec![Node::default()] }
    }

    fn find(&self, prefix: &str) -> Option<usize> {
        let mut at = 0;
        for byte in prefix.bytes() {
            at = *self.nodes[at].children.get(&byte)?;
        }
        Some(at)
    }

    fn contains(&self, word: &str) -> bool {
        self.find(word).is_some_and(|n| self.nodes[n].terminal)
    }

    /// Returns Ok(true) if the word was new.
    fn insert(&mut self, word: &str) -> Result<bool, TrieError> {
        if !word.is_ascii() {
            return Err(TrieError::NonAscii);
        }
        if self.contains(word) {
            return Ok(false);
        }
        let mut at = 0;
        self.nodes[0].words += 1;
        for byte in word.bytes() {
            at = match self.nodes[at].children.get(&byte) {
                Some(&next) => next,
                None => {
                    self.nodes.push(Node::default());
                    let next = self.nodes.len() - 1;
                    self.nodes[at].children.insert(byte, next);
                    next
                }
            };
            self.nodes[at].words += 1;
        }
        self.nodes[at].terminal = true;
        Ok(true)
    }

    fn count_prefix(&self, prefix: &str) -> usize {
        self.find(prefix).map_or(0, |n| self.nodes[n].words)
    }

    /// Words starting with `prefix`, in lexicographic order, at most `limit`.
    fn with_prefix(&self, prefix: &str, limit: usize) -> Vec<String> {
        let mut out = Vec::new();
        if let Some(start) = self.find(prefix) {
            let mut buffer = prefix.as_bytes().to_vec();
            self.collect(start, &mut buffer, limit, &mut out);
        }
        out
    }

    fn collect(&self, at: usize, buffer: &mut Vec<u8>, limit: usize, out: &mut Vec<String>) {
        if out.len() >= limit {
            return;
        }
        if self.nodes[at].terminal {
            out.push(String::from_utf8(buffer.clone()).unwrap());
        }
        for (&byte, &next) in &self.nodes[at].children {
            buffer.push(byte);
            self.collect(next, buffer, limit, out);
            buffer.pop();
        }
    }
}
