impl Trie {
    fn longest_common_prefix(&self) -> String {
        let mut at = 0;
        let mut prefix = Vec::new();
        while self.nodes[at].children.len() == 1 && !self.nodes[at].terminal {
            let (&byte, &next) = self.nodes[at].children.iter().next().unwrap();
            prefix.push(byte);
            at = next;
        }
        String::from_utf8(prefix).unwrap()
    }
