const IOC: u32 = 1 << 0;
const POST_ONLY: u32 = 1 << 1;
const HIDDEN: u32 = 1 << 2;
const REDUCE_ONLY: u32 = 1 << 3;

const NAMES: [&str; 4] = ["IOC", "POST_ONLY", "HIDDEN", "REDUCE_ONLY"];

/// Visit each set bit using x &= x - 1 to clear the lowest one.
fn set_bits(mut x: u32) -> impl Iterator<Item = u32> {
    std::iter::from_fn(move || {
        if x == 0 {
            return None;
        }
        let bit = x.trailing_zeros();
        x &= x - 1;
        Some(bit)
    })
}

fn flag_names(flags: u32) -> Vec<&'static str> {
    set_bits(flags).filter_map(|bit| NAMES.get(bit as usize).copied()).collect()
}

fn is_power_of_two(x: u32) -> bool {
    x != 0 && x & (x - 1) == 0
}

fn single_number(values: &[u32]) -> u32 {
    values.iter().fold(0, |acc, &v| acc ^ v)
}

fn bits_to_flip(a: u32, b: u32) -> u32 {
    (a ^ b).count_ones()
}

fn extract(x: u32, shift: u32, width: u32) -> Option<u32> {
    let mask = 1u32.checked_shl(width)?.wrapping_sub(1); // width 32 returns None: a full-width mask needs its own case
    Some(x.checked_shr(shift)? & mask)
}

fn popcount_loop(mut x: u32) -> u32 {
    let mut n = 0;
    while x != 0 {
        n += x & 1;
        x >>= 1;
    }
    n
}

fn main() {
    let mut flags = IOC | HIDDEN;
    println!("flags = {flags:#06b} -> {:?}", flag_names(flags));
    flags |= POST_ONLY;
    flags &= !IOC;
    flags ^= REDUCE_ONLY;
    println!("after set, clear, toggle: {flags:#06b} -> {:?}", flag_names(flags));
    println!("has HIDDEN: {}, has IOC: {}", flags & HIDDEN != 0, flags & IOC != 0);

    let x = 0b1011_0100u32;
    println!("x = {x:#010b}, lowest set bit = {:#b}, cleared = {:#010b}", x & x.wrapping_neg(), x & (x - 1));
    println!("set bit positions: {:?}", set_bits(x).collect::<Vec<_>>());
    println!("single number in [4, 7, 4, 9, 7]: {}", single_number(&[4, 7, 4, 9, 7]));
    println!("bits to flip 29 -> 15: {}", bits_to_flip(29, 15));
    println!("swap nibbles of 0xA5: {:#04x}", 0xA5u8.rotate_left(4));
    println!("extract bits 4..8 of 0xABCD: {:#x}", extract(0xABCD, 4, 4).unwrap());
    println!("shift by 32 is not an overflow with checked_shl: {:?}", 1u32.checked_shl(32));
    println!("arithmetic -8 >> 1 = {}, logical = {}", -8i32 >> 1, (-8i32 as u32) >> 1);

    for x in 0..=u16::MAX as u32 {
        assert_eq!(x.count_ones(), popcount_loop(x));
        assert_eq!(is_power_of_two(x), x != 0 && x.next_power_of_two() == x);
        assert_eq!(x.reverse_bits() >> 16, (0..16).fold(0, |acc, i| acc | (((x >> i) & 1) << (15 - i))));
        if x != 0 {
            assert_eq!(x & x.wrapping_neg(), 1 << x.trailing_zeros());
        }
        assert_eq!(set_bits(x).count() as u32, x.count_ones());
    }
    println!("tricks match the plain loops for every 16-bit value: true");
}

