struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }

    fn range(&mut self, low: i64, high: i64) -> i64 {
        low + (self.next() % (high - low + 1) as u64) as i64
    }
}
fn percentile_f64(values: &mut [f64], per_10000: u64) -> Option<f64> {
    if values.is_empty() || values.iter().any(|v| v.is_nan()) {
        return None;
    }
    let rank = (values.len() as u64 * per_10000).div_ceil(10_000).max(1) as usize;
    let (_, nth, _) = values.select_nth_unstable_by(rank - 1, f64::total_cmp);
    Some(*nth)
}

fn main() {
    let mut rng = Rng(8);
    for _ in 0..1000 {
        let n = rng.range(1, 60) as usize;
        let values: Vec<f64> = (0..n).map(|_| rng.range(-500, 500) as f64 / 10.0).collect();
        for p in [1, 2500, 5000, 9500, 9900, 10_000] {
            let mut sorted = values.clone();
            sorted.sort_by(f64::total_cmp);
            let rank = (n as u64 * p).div_ceil(10_000).max(1) as usize;
            assert_eq!(percentile_f64(&mut values.clone(), p), Some(sorted[rank - 1]));
        }
    }
    assert_eq!(percentile_f64(&mut [], 5000), None);
    assert_eq!(percentile_f64(&mut [1.0, f64::NAN], 5000), None);
    println!("p90 of 1..=10 = {:?}", percentile_f64(&mut (1..=10).map(f64::from).collect::<Vec<_>>(), 9000));
}

